import { useCallback, useEffect, useRef, useState } from "react";

interface ChatMessage {
  id: string;
  author: string;
  text: string;
  sentAt: string;
}

interface ChatRoomProps {
  roomId: string;
}

const MAX_RECONNECT_DELAY_MS = 10_000;
const BASE_RECONNECT_DELAY_MS = 500;
const MAX_MESSAGES = 500;

function isChatMessage(value: unknown): value is ChatMessage {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.id === "string" &&
    typeof candidate.author === "string" &&
    typeof candidate.text === "string" &&
    typeof candidate.sentAt === "string"
  );
}

export function ChatRoom({ roomId }: ChatRoomProps) {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [draft, setDraft] = useState("");
  const [isReconnecting, setIsReconnecting] = useState(false);

  const socketRef = useRef<WebSocket | null>(null);
  const reconnectTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const reconnectAttemptRef = useRef(0);
  const closingForSwitchRef = useRef(false);
  const bottomRef = useRef<HTMLDivElement | null>(null);

  const prevRoomIdRef = useRef(roomId);
  if (prevRoomIdRef.current !== roomId) {
    prevRoomIdRef.current = roomId;
    setMessages([]);
    setDraft("");
  }

  useEffect(() => {
    reconnectAttemptRef.current = 0;
    closingForSwitchRef.current = false;

    let cancelled = false;

    const connect = () => {
      if (cancelled) return;

      const socket = new WebSocket(
        `wss://chat.example.com/rooms/${encodeURIComponent(roomId)}`,
      );
      socketRef.current = socket;

      socket.onopen = () => {
        if (cancelled) return;
        reconnectAttemptRef.current = 0;
        setIsReconnecting(false);
      };

      socket.onmessage = (event) => {
        if (cancelled) return;
        try {
          const parsed: unknown = JSON.parse(event.data as string);
          if (isChatMessage(parsed)) {
            setMessages((prev) =>
              [...prev, parsed].slice(-MAX_MESSAGES),
            );
          }
        } catch (error) {
          console.warn("Failed to parse chat message payload", error);
        }
      };

      socket.onclose = () => {
        if (cancelled || closingForSwitchRef.current) return;
        setIsReconnecting(true);
        const attempt = reconnectAttemptRef.current + 1;
        reconnectAttemptRef.current = attempt;
        const delay = Math.min(
          BASE_RECONNECT_DELAY_MS * 2 ** (attempt - 1),
          MAX_RECONNECT_DELAY_MS,
        );
        reconnectTimeoutRef.current = setTimeout(connect, delay);
      };

      socket.onerror = () => {
        socket.close();
      };
    };

    connect();

    return () => {
      cancelled = true;
      closingForSwitchRef.current = true;
      if (reconnectTimeoutRef.current !== null) {
        clearTimeout(reconnectTimeoutRef.current);
        reconnectTimeoutRef.current = null;
      }
      socketRef.current?.close();
      socketRef.current = null;
    };
  }, [roomId]);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ block: "end" });
  }, [messages]);

  const sendMessage = useCallback(() => {
    const text = draft.trim();
    const socket = socketRef.current;
    if (!text || !socket || socket.readyState !== WebSocket.OPEN) return;
    socket.send(JSON.stringify({ text }));
    setDraft("");
  }, [draft]);

  const handleSubmit = useCallback(
    (event: React.FormEvent<HTMLFormElement>) => {
      event.preventDefault();
      sendMessage();
    },
    [sendMessage],
  );

  return (
    <div className="chat-room">
      {isReconnecting && <div className="chat-room__banner">Reconnecting…</div>}
      <ul className="chat-room__messages">
        {messages.map((message) => (
          <li key={message.id} className="chat-room__message">
            <span className="chat-room__author">{message.author}</span>
            <span className="chat-room__text">{message.text}</span>
            <time className="chat-room__time" dateTime={message.sentAt}>
              {new Date(message.sentAt).toLocaleTimeString()}
            </time>
          </li>
        ))}
      </ul>
      <div ref={bottomRef} />
      <form className="chat-room__form" onSubmit={handleSubmit}>
        <input
          type="text"
          value={draft}
          onChange={(event) => setDraft(event.target.value)}
          placeholder="Type a message…"
        />
        <button type="submit">Send</button>
      </form>
    </div>
  );
}

export default ChatRoom;

import { useEffect, useRef, useState } from "react";

interface Metric {
  name: string;
  value: number;
  unit: string;
}

const POLL_INTERVAL_MS = 10_000;

const styles: Record<string, React.CSSProperties> = {
  panel: {
    border: "1px solid #d0d7de",
    borderRadius: 8,
    padding: 16,
    maxWidth: 480,
    fontFamily: "system-ui, sans-serif",
  },
  header: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "baseline",
    marginBottom: 12,
  },
  title: {
    margin: 0,
    fontSize: 16,
    fontWeight: 600,
  },
  updated: {
    fontSize: 12,
    color: "#57606a",
  },
  error: {
    color: "#cf222e",
    fontSize: 13,
    marginBottom: 8,
  },
  table: {
    width: "100%",
    borderCollapse: "collapse",
  },
  row: {
    borderTop: "1px solid #eaeef2",
    transition: "background-color 0.6s ease",
  },
  rowChanged: {
    backgroundColor: "#fff8c5",
  },
  cell: {
    padding: "6px 4px",
    fontSize: 14,
    textAlign: "left",
  },
  valueCell: {
    padding: "6px 4px",
    fontSize: 14,
    textAlign: "right",
    fontVariantNumeric: "tabular-nums",
  },
};

function isMetric(value: unknown): value is Metric {
  if (typeof value !== "object" || value === null) {
    return false;
  }
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.name === "string" &&
    typeof candidate.value === "number" &&
    Number.isFinite(candidate.value) &&
    typeof candidate.unit === "string"
  );
}

function isMetricArray(value: unknown): value is Metric[] {
  return Array.isArray(value) && value.every(isMetric);
}

function formatSecondsAgo(lastUpdated: Date | null, now: Date): string {
  if (lastUpdated === null) {
    return "never";
  }
  const seconds = Math.max(0, Math.round((now.getTime() - lastUpdated.getTime()) / 1000));
  if (seconds === 0) {
    return "just now";
  }
  return `${seconds} second${seconds === 1 ? "" : "s"} ago`;
}

export default function MetricsPanel(): React.JSX.Element {
  const [metrics, setMetrics] = useState<Metric[]>([]);
  const [changedNames, setChangedNames] = useState<ReadonlySet<string>>(new Set());
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [now, setNow] = useState<Date>(() => new Date());

  const previousValuesRef = useRef<Map<string, number>>(new Map());

  useEffect(() => {
    let cancelled = false;
    let isPolling = false;
    let pollTimeoutId: ReturnType<typeof setTimeout> | null = null;
    // Bumped whenever polling starts/stops so a stale in-flight request
    // (e.g. from before the tab was hidden) can't apply its result or
    // reschedule once a newer poll loop has taken over.
    let generation = 0;

    async function fetchMetrics(requestGeneration: number): Promise<void> {
      try {
        const response = await fetch("/api/metrics");
        if (!response.ok) {
          throw new Error(`Request failed with status ${response.status}`);
        }
        const responseBody: unknown = await response.json();
        if (cancelled || requestGeneration !== generation) {
          return;
        }
        if (!isMetricArray(responseBody)) {
          throw new Error("Received malformed metrics data");
        }
        const fetchedMetrics = responseBody;

        const previousValues = previousValuesRef.current;
        const changed = new Set<string>();
        for (const metric of fetchedMetrics) {
          const previousValue = previousValues.get(metric.name);
          if (previousValue !== undefined && previousValue !== metric.value) {
            changed.add(metric.name);
          }
        }
        previousValuesRef.current = new Map(
          fetchedMetrics.map((metric) => [metric.name, metric.value]),
        );

        setMetrics(fetchedMetrics);
        setChangedNames(changed);
        setLastUpdated(new Date());
        setError(null);
      } catch (err) {
        if (!cancelled && requestGeneration === generation) {
          setError(err instanceof Error ? err.message : "Failed to load metrics");
        }
      }
    }

    async function pollOnce(requestGeneration: number): Promise<void> {
      await fetchMetrics(requestGeneration);
      if (isPolling && !cancelled && requestGeneration === generation) {
        pollTimeoutId = setTimeout(() => {
          void pollOnce(requestGeneration);
        }, POLL_INTERVAL_MS);
      }
    }

    function startPolling(): void {
      if (isPolling) {
        return;
      }
      isPolling = true;
      generation += 1;
      void pollOnce(generation);
    }

    function stopPolling(): void {
      isPolling = false;
      generation += 1;
      if (pollTimeoutId !== null) {
        clearTimeout(pollTimeoutId);
        pollTimeoutId = null;
      }
    }

    function handleVisibilityChange(): void {
      if (document.hidden) {
        stopPolling();
      } else {
        startPolling();
      }
    }

    if (!document.hidden) {
      startPolling();
    }

    document.addEventListener("visibilitychange", handleVisibilityChange);

    return () => {
      cancelled = true;
      stopPolling();
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, []);

  useEffect(() => {
    const tickId = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(tickId);
  }, []);

  return (
    <div style={styles.panel}>
      <div style={styles.header}>
        <h2 style={styles.title}>Metrics</h2>
        <span style={styles.updated}>Last updated {formatSecondsAgo(lastUpdated, now)}</span>
      </div>

      {error !== null && <div style={styles.error}>{error}</div>}

      {metrics.length === 0 && error === null ? (
        <div>Loading metrics…</div>
      ) : (
        <table style={styles.table}>
          <thead>
            <tr>
              <th style={styles.cell} scope="col">
                Name
              </th>
              <th style={styles.valueCell} scope="col">
                Value
              </th>
            </tr>
          </thead>
          <tbody>
            {metrics.map((metric) => {
              const rowStyle = changedNames.has(metric.name)
                ? { ...styles.row, ...styles.rowChanged }
                : styles.row;
              return (
                <tr key={metric.name} style={rowStyle}>
                  <td style={styles.cell}>{metric.name}</td>
                  <td style={styles.valueCell}>
                    {metric.value} {metric.unit}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      )}
    </div>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";

interface User {
  id: string;
  name: string;
  email: string;
}

type SortField = "name" | "email";

const DEBOUNCE_MS = 300;

function isUser(value: unknown): value is User {
  if (typeof value !== "object" || value === null) {
    return false;
  }
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.id === "string" &&
    typeof candidate.name === "string" &&
    typeof candidate.email === "string"
  );
}

function isUserArray(value: unknown): value is User[] {
  return Array.isArray(value) && value.every(isUser);
}

export default function UserSearch() {
  const [query, setQuery] = useState("");
  const [debouncedQuery, setDebouncedQuery] = useState("");
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [sortField, setSortField] = useState<SortField>("name");
  const requestIdRef = useRef(0);

  useEffect(() => {
    const timer = setTimeout(() => setDebouncedQuery(query), DEBOUNCE_MS);
    return () => clearTimeout(timer);
  }, [query]);

  function handleQueryChange(value: string) {
    setQuery(value);
    setUsers([]);
    setError(null);
    setLoading(value.trim() !== "");
  }

  useEffect(() => {
    if (debouncedQuery.trim() === "") {
      setUsers([]);
      setError(null);
      setLoading(false);
      return;
    }

    const requestId = ++requestIdRef.current;
    const controller = new AbortController();
    setLoading(true);
    setError(null);

    fetch(`/api/users?q=${encodeURIComponent(debouncedQuery)}`, {
      signal: controller.signal,
    })
      .then((res) => {
        if (!res.ok) {
          throw new Error(`Request failed with status ${res.status}`);
        }
        return res.json() as Promise<unknown>;
      })
      .then((payload) => {
        if (requestIdRef.current !== requestId) {
          return;
        }
        if (!isUserArray(payload)) {
          throw new Error("Received malformed user data");
        }
        setUsers(payload);
        setLoading(false);
      })
      .catch((err: unknown) => {
        if (requestIdRef.current !== requestId) {
          return;
        }
        if (err instanceof DOMException && err.name === "AbortError") {
          return;
        }
        setError(err instanceof Error ? err.message : "Failed to fetch users");
        setUsers([]);
        setLoading(false);
      });

    return () => controller.abort();
  }, [debouncedQuery]);

  const sortedUsers = useMemo(() => {
    return [...users].sort((a, b) => a[sortField].localeCompare(b[sortField]));
  }, [users, sortField]);

  return (
    <div>
      <input
        type="text"
        value={query}
        onChange={(e) => handleQueryChange(e.target.value)}
        placeholder="Search users..."
        aria-label="Search users"
      />

      <div>
        <label htmlFor="sort-field">Sort by: </label>
        <select
          id="sort-field"
          value={sortField}
          onChange={(e) => setSortField(e.target.value as SortField)}
        >
          <option value="name">Name</option>
          <option value="email">Email</option>
        </select>
      </div>

      {loading && <p role="status">Loading...</p>}
      {error && <p role="alert">Error: {error}</p>}

      {!loading && !error && debouncedQuery.trim() !== "" && (
        <p>
          {sortedUsers.length} result{sortedUsers.length === 1 ? "" : "s"}
        </p>
      )}

      <ul>
        {sortedUsers.map((user) => (
          <li key={user.id}>
            {user.name} ({user.email})
          </li>
        ))}
      </ul>
    </div>
  );
}

import Foundation
import SwiftUI

struct SearchResult: Identifiable, Decodable {
    let id: String
    let title: String
    let subtitle: String
}

@MainActor
final class SearchViewModel: ObservableObject {
    @Published var query: String = "" {
        didSet { scheduleSearch() }
    }
    @Published private(set) var results: [SearchResult] = []
    @Published private(set) var isLoading = false
    @Published private(set) var errorMessage: String?

    private var searchTask: Task<Void, Never>?
    private let debounceInterval: Duration = .milliseconds(300)
    private let session: URLSession

    init(session: URLSession = .shared) {
        self.session = session
    }

    deinit {
        searchTask?.cancel()
    }

    private func scheduleSearch() {
        searchTask?.cancel()

        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            results = []
            errorMessage = nil
            isLoading = false
            return
        }

        searchTask = Task {
            try? await Task.sleep(for: debounceInterval)
            guard !Task.isCancelled else { return }
            await performSearch(for: trimmed)
        }
    }

    private func performSearch(for text: String) async {
        isLoading = true
        errorMessage = nil

        var components = URLComponents(string: "https://api.example.com/search")
        components?.queryItems = [URLQueryItem(name: "q", value: text)]

        guard let url = components?.url else {
            isLoading = false
            errorMessage = "Invalid search URL."
            return
        }

        do {
            let (data, response) = try await session.data(from: url)
            guard !Task.isCancelled else { return }

            guard let httpResponse = response as? HTTPURLResponse else {
                throw URLError(.badServerResponse)
            }
            guard (200..<300).contains(httpResponse.statusCode) else {
                throw URLError(.badServerResponse)
            }

            let decoded = try await Task.detached(priority: .userInitiated) {
                try JSONDecoder().decode([SearchResult].self, from: data)
            }.value
            guard !Task.isCancelled else { return }
            results = decoded
            isLoading = false
        } catch {
            guard !Task.isCancelled else { return }
            results = []
            isLoading = false
            errorMessage = error.localizedDescription
        }
    }
}

struct SearchScreen: View {
    @StateObject private var viewModel = SearchViewModel()

    var body: some View {
        VStack(spacing: 0) {
            TextField("Search", text: $viewModel.query)
                .textFieldStyle(.roundedBorder)
                .padding()

            content
        }
        .frame(minWidth: 320, minHeight: 400)
    }

    @ViewBuilder
    private var content: some View {
        if viewModel.isLoading {
            ProgressView()
                .frame(maxWidth: .infinity, maxHeight: .infinity)
        } else if let errorMessage = viewModel.errorMessage {
            Text(errorMessage)
                .foregroundStyle(.red)
                .frame(maxWidth: .infinity, maxHeight: .infinity)
        } else if viewModel.query.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            Text("Start typing to search.")
                .foregroundStyle(.secondary)
                .frame(maxWidth: .infinity, maxHeight: .infinity)
        } else if viewModel.results.isEmpty {
            Text("No results.")
                .foregroundStyle(.secondary)
                .frame(maxWidth: .infinity, maxHeight: .infinity)
        } else {
            List(viewModel.results) { result in
                VStack(alignment: .leading) {
                    Text(result.title)
                    Text(result.subtitle)
                        .font(.subheadline)
                        .foregroundStyle(.secondary)
                }
            }
        }
    }
}

import { useEffect, useMemo, useRef, useState } from "react";
import type { ChangeEvent, FormEvent } from "react";

interface Todo {
  id: string;
  text: string;
  done: boolean;
}

type Filter = "all" | "active" | "done";

const STORAGE_KEY = "todo-board:items";

function isTodo(value: unknown): value is Todo {
  return (
    typeof value === "object" &&
    value !== null &&
    typeof (value as Todo).id === "string" &&
    typeof (value as Todo).text === "string" &&
    typeof (value as Todo).done === "boolean"
  );
}

function loadTodos(): Todo[] {
  if (typeof localStorage === "undefined") return [];
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed.filter(isTodo);
  } catch {
    return [];
  }
}

function createId(): string {
  return `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
}

export default function TodoBoard() {
  const [todos, setTodos] = useState<Todo[]>(() => loadTodos());
  const [newText, setNewText] = useState("");
  const [filter, setFilter] = useState<Filter>("all");
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editingText, setEditingText] = useState("");
  const cancelingEditRef = useRef(false);

  useEffect(() => {
    if (typeof localStorage === "undefined") return;
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
    } catch (error) {
      console.warn("Failed to persist todos to localStorage", error);
    }
  }, [todos]);

  const remainingCount = useMemo(
    () => todos.filter((todo) => !todo.done).length,
    [todos],
  );

  const visibleTodos = useMemo(() => {
    switch (filter) {
      case "active":
        return todos.filter((todo) => !todo.done);
      case "done":
        return todos.filter((todo) => todo.done);
      default:
        return todos;
    }
  }, [todos, filter]);

  function handleAdd(event: FormEvent) {
    event.preventDefault();
    const text = newText.trim();
    if (!text) return;
    setTodos((prev) => [...prev, { id: createId(), text, done: false }]);
    setNewText("");
  }

  function handleToggle(id: string) {
    setTodos((prev) =>
      prev.map((todo) =>
        todo.id === id ? { ...todo, done: !todo.done } : todo,
      ),
    );
  }

  function handleDelete(id: string) {
    setTodos((prev) => prev.filter((todo) => todo.id !== id));
    if (editingId === id) {
      setEditingId(null);
      setEditingText("");
    }
  }

  function startEdit(todo: Todo) {
    setEditingId(todo.id);
    setEditingText(todo.text);
  }

  function cancelEdit() {
    setEditingId(null);
    setEditingText("");
  }

  function commitEdit(id: string) {
    const text = editingText.trim();
    if (!text) {
      handleDelete(id);
      return;
    }
    setTodos((prev) =>
      prev.map((todo) => (todo.id === id ? { ...todo, text } : todo)),
    );
    setEditingId(null);
    setEditingText("");
  }

  function moveUp(index: number) {
    if (index === 0) return;
    setTodos((prev) => {
      const next = [...prev];
      [next[index - 1], next[index]] = [next[index], next[index - 1]];
      return next;
    });
  }

  function moveDown(index: number) {
    setTodos((prev) => {
      if (index === prev.length - 1) return prev;
      const next = [...prev];
      [next[index], next[index + 1]] = [next[index + 1], next[index]];
      return next;
    });
  }

  return (
    <div className="todo-board">
      <h1>Todo Board</h1>

      <form onSubmit={handleAdd} className="todo-add-form">
        <input
          type="text"
          value={newText}
          placeholder="Add a new todo…"
          onChange={(event: ChangeEvent<HTMLInputElement>) =>
            setNewText(event.target.value)
          }
        />
        <button type="submit">Add</button>
      </form>

      <div className="todo-filters">
        {(["all", "active", "done"] as Filter[]).map((option) => (
          <button
            key={option}
            type="button"
            aria-pressed={filter === option}
            onClick={() => setFilter(option)}
          >
            {option[0].toUpperCase() + option.slice(1)}
          </button>
        ))}
      </div>

      <p className="todo-count">
        {remainingCount} item{remainingCount === 1 ? "" : "s"} remaining
      </p>

      <ul className="todo-list">
        {visibleTodos.map((todo) => {
          const index = todos.findIndex((item) => item.id === todo.id);
          const isEditing = editingId === todo.id;
          return (
            <li key={todo.id} className="todo-item">
              <input
                type="checkbox"
                checked={todo.done}
                onChange={() => handleToggle(todo.id)}
              />

              {isEditing ? (
                <input
                  type="text"
                  value={editingText}
                  autoFocus
                  onChange={(event: ChangeEvent<HTMLInputElement>) =>
                    setEditingText(event.target.value)
                  }
                  onBlur={() => {
                    if (cancelingEditRef.current) {
                      cancelingEditRef.current = false;
                      return;
                    }
                    commitEdit(todo.id);
                  }}
                  onKeyDown={(event) => {
                    if (event.key === "Enter") {
                      event.preventDefault();
                      commitEdit(todo.id);
                    } else if (event.key === "Escape") {
                      cancelingEditRef.current = true;
                      cancelEdit();
                    }
                  }}
                />
              ) : (
                <span
                  className={todo.done ? "todo-text done" : "todo-text"}
                  onDoubleClick={() => startEdit(todo)}
                >
                  {todo.text}
                </span>
              )}

              <div className="todo-actions">
                <button
                  type="button"
                  onClick={() => moveUp(index)}
                  disabled={index === 0}
                  aria-label="Move up"
                >
                  ↑
                </button>
                <button
                  type="button"
                  onClick={() => moveDown(index)}
                  disabled={index === todos.length - 1}
                  aria-label="Move down"
                >
                  ↓
                </button>
                {isEditing ? (
                  <button type="button" onClick={() => commitEdit(todo.id)}>
                    Save
                  </button>
                ) : (
                  <button type="button" onClick={() => startEdit(todo)}>
                    Edit
                  </button>
                )}
                <button type="button" onClick={() => handleDelete(todo.id)}>
                  Delete
                </button>
              </div>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

import { useRef, useState, FormEvent } from "react";

type FormFields = "name" | "email" | "password" | "confirmPassword" | "acceptTerms";

interface FormState {
  name: string;
  email: string;
  password: string;
  confirmPassword: string;
  acceptTerms: boolean;
}

type FieldErrors = Partial<Record<FormFields, string>>;

const initialState: FormState = {
  name: "",
  email: "",
  password: "",
  confirmPassword: "",
  acceptTerms: false,
};

const FORM_FIELDS: FormFields[] = ["name", "email", "password", "confirmPassword", "acceptTerms"];

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function validate(form: FormState): FieldErrors {
  const errors: FieldErrors = {};

  if (!form.name.trim()) {
    errors.name = "Name is required.";
  }

  if (!form.email.trim()) {
    errors.email = "Email is required.";
  } else if (!EMAIL_PATTERN.test(form.email)) {
    errors.email = "Enter a valid email address.";
  }

  if (!form.password) {
    errors.password = "Password is required.";
  } else if (form.password.length < 8) {
    errors.password = "Password must be at least 8 characters.";
  }

  if (!form.confirmPassword) {
    errors.confirmPassword = "Please confirm your password.";
  } else if (form.confirmPassword !== form.password) {
    errors.confirmPassword = "Passwords do not match.";
  }

  if (!form.acceptTerms) {
    errors.acceptTerms = "You must accept the terms to continue.";
  }

  return errors;
}

interface SignupSuccessResponse {
  id: string;
}

interface SignupErrorResponse {
  errors: Partial<Record<FormFields, string>>;
}

function isSignupErrorResponse(body: unknown): body is SignupErrorResponse {
  return (
    typeof body === "object" &&
    body !== null &&
    "errors" in body &&
    typeof (body as { errors: unknown }).errors === "object" &&
    (body as { errors: unknown }).errors !== null
  );
}

function isSignupSuccessResponse(body: unknown): body is SignupSuccessResponse {
  return (
    typeof body === "object" &&
    body !== null &&
    "id" in body &&
    typeof (body as { id: unknown }).id === "string"
  );
}

function sanitizeFieldErrors(errors: Record<string, unknown>): FieldErrors {
  const sanitized: FieldErrors = {};
  for (const field of FORM_FIELDS) {
    const value = errors[field];
    if (typeof value === "string" && value.trim().length > 0) {
      sanitized[field] = value;
    }
  }
  return sanitized;
}

export default function SignupForm() {
  const [form, setForm] = useState<FormState>(initialState);
  const [errors, setErrors] = useState<FieldErrors>({});
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [accountId, setAccountId] = useState<string | null>(null);
  const submittingRef = useRef(false);

  function updateField<K extends keyof FormState>(field: K, value: FormState[K]) {
    setForm((prev) => ({ ...prev, [field]: value }));
    setErrors((prev) => ({ ...prev, [field]: undefined }));
  }

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();

    if (submittingRef.current) {
      return;
    }

    setSubmitError(null);

    const validationErrors = validate(form);
    if (Object.keys(validationErrors).length > 0) {
      setErrors(validationErrors);
      return;
    }

    submittingRef.current = true;
    setSubmitting(true);
    try {
      const response = await fetch("/api/signup", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: form.name,
          email: form.email,
          password: form.password,
          acceptTerms: form.acceptTerms,
        }),
      });

      const responseBody: unknown = await response.json().catch(() => null);

      if (!response.ok) {
        if (isSignupErrorResponse(responseBody)) {
          const sanitizedErrors = sanitizeFieldErrors(responseBody.errors);
          if (Object.keys(sanitizedErrors).length > 0) {
            setErrors(sanitizedErrors);
          } else {
            setSubmitError("Something went wrong. Please try again.");
          }
        } else {
          setSubmitError("Something went wrong. Please try again.");
        }
        return;
      }

      if (!isSignupSuccessResponse(responseBody)) {
        setSubmitError("Unexpected response from server.");
        return;
      }

      setAccountId(responseBody.id);
      setForm(initialState);
      setErrors({});
    } catch {
      setSubmitError("Network error. Please try again.");
    } finally {
      submittingRef.current = false;
      setSubmitting(false);
    }
  }

  if (accountId) {
    return (
      <div role="status">
        <p>Account created successfully! Your account id is {accountId}.</p>
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} noValidate>
      <div>
        <label htmlFor="name">Name</label>
        <input
          id="name"
          type="text"
          value={form.name}
          onChange={(e) => updateField("name", e.target.value)}
          disabled={submitting}
          aria-invalid={errors.name ? true : undefined}
          aria-describedby={errors.name ? "name-error" : undefined}
        />
        {errors.name && (
          <span id="name-error" role="alert">
            {errors.name}
          </span>
        )}
      </div>

      <div>
        <label htmlFor="email">Email</label>
        <input
          id="email"
          type="email"
          value={form.email}
          onChange={(e) => updateField("email", e.target.value)}
          disabled={submitting}
          aria-invalid={errors.email ? true : undefined}
          aria-describedby={errors.email ? "email-error" : undefined}
        />
        {errors.email && (
          <span id="email-error" role="alert">
            {errors.email}
          </span>
        )}
      </div>

      <div>
        <label htmlFor="password">Password</label>
        <input
          id="password"
          type="password"
          value={form.password}
          onChange={(e) => updateField("password", e.target.value)}
          disabled={submitting}
          aria-invalid={errors.password ? true : undefined}
          aria-describedby={errors.password ? "password-error" : undefined}
        />
        {errors.password && (
          <span id="password-error" role="alert">
            {errors.password}
          </span>
        )}
      </div>

      <div>
        <label htmlFor="confirmPassword">Confirm Password</label>
        <input
          id="confirmPassword"
          type="password"
          value={form.confirmPassword}
          onChange={(e) => updateField("confirmPassword", e.target.value)}
          disabled={submitting}
          aria-invalid={errors.confirmPassword ? true : undefined}
          aria-describedby={errors.confirmPassword ? "confirmPassword-error" : undefined}
        />
        {errors.confirmPassword && (
          <span id="confirmPassword-error" role="alert">
            {errors.confirmPassword}
          </span>
        )}
      </div>

      <div>
        <label htmlFor="acceptTerms">
          <input
            id="acceptTerms"
            type="checkbox"
            checked={form.acceptTerms}
            onChange={(e) => updateField("acceptTerms", e.target.checked)}
            disabled={submitting}
            aria-invalid={errors.acceptTerms ? true : undefined}
            aria-describedby={errors.acceptTerms ? "acceptTerms-error" : undefined}
          />
          I accept the terms and conditions
        </label>
        {errors.acceptTerms && (
          <span id="acceptTerms-error" role="alert">
            {errors.acceptTerms}
          </span>
        )}
      </div>

      {submitError && <p role="alert">{submitError}</p>}

      <button type="submit" disabled={submitting}>
        {submitting ? "Signing up..." : "Sign up"}
      </button>
    </form>
  );
}

import { useEffect, useMemo, useState } from "react";
import type { User } from "./ProfileEditor";

export interface UserProfileState {
  data: User | null;
  loading: boolean;
  error: string | null;
}

export interface UseUserProfilesResult {
  profiles: Record<string, UserProfileState>;
  loading: boolean;
}

function isUser(value: unknown): value is User {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.id === "string" &&
    typeof candidate.displayName === "string" &&
    typeof candidate.bio === "string" &&
    typeof candidate.avatarUrl === "string"
  );
}

async function fetchUser(id: string, signal: AbortSignal): Promise<User> {
  const response = await fetch(`/api/users/${encodeURIComponent(id)}`, { signal });
  if (!response.ok) {
    throw new Error(`Failed to load user ${id}: ${response.status}`);
  }
  const body: unknown = await response.json();
  if (!isUser(body)) {
    throw new Error(`Malformed user response for ${id}`);
  }
  if (body.id !== id) {
    throw new Error(`Requested user ${id} but received ${body.id}`);
  }
  return body;
}

function getOwnProfile(
  profiles: Record<string, UserProfileState>,
  id: string
): UserProfileState | undefined {
  return Object.prototype.hasOwnProperty.call(profiles, id) ? profiles[id] : undefined;
}

export function useUserProfiles(ids: string[]): UseUserProfilesResult {
  const [profiles, setProfiles] = useState<Record<string, UserProfileState>>({});

  const key = JSON.stringify(ids);

  useEffect(() => {
    const controller = new AbortController();

    setProfiles(
      Object.fromEntries(
        ids.map((id) => [id, { data: null, loading: true, error: null } as UserProfileState])
      )
    );

    ids.forEach((id) => {
      fetchUser(id, controller.signal)
        .then((data) => {
          if (controller.signal.aborted) return;
          setProfiles((prev) => ({ ...prev, [id]: { data, loading: false, error: null } }));
        })
        .catch((err) => {
          if (controller.signal.aborted) return;
          const message = err instanceof Error ? err.message : "Failed to load user";
          setProfiles((prev) => ({ ...prev, [id]: { data: null, loading: false, error: message } }));
        });
    });

    return () => controller.abort();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key]);

  const visibleProfiles = useMemo(() => {
    const profilesForCurrentIds: Record<string, UserProfileState> = {};
    for (const id of ids) {
      profilesForCurrentIds[id] = getOwnProfile(profiles, id) ?? { data: null, loading: true, error: null };
    }
    return profilesForCurrentIds;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key, profiles]);

  const loading = ids.some((id) => visibleProfiles[id].loading);

  return { profiles: visibleProfiles, loading };
}

import { useState } from "react";

export interface User {
  id: string;
  displayName: string;
  bio: string;
  avatarUrl: string;
}

export interface ProfileEditorProps {
  user: User;
  onSave: (user: User) => Promise<void>;
}

export function ProfileEditor({ user, onSave }: ProfileEditorProps) {
  const [displayName, setDisplayName] = useState(user.displayName);
  const [bio, setBio] = useState(user.bio);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [loadedUserId, setLoadedUserId] = useState(user.id);

  if (user.id !== loadedUserId) {
    setLoadedUserId(user.id);
    setDisplayName(user.displayName);
    setBio(user.bio);
    setSaving(false);
    setError(null);
  }

  const hasChanges = displayName !== user.displayName || bio !== user.bio;

  const handleReset = () => {
    setDisplayName(user.displayName);
    setBio(user.bio);
    setError(null);
  };

  const handleSave = async () => {
    if (!hasChanges || saving) return;
    setSaving(true);
    setError(null);
    try {
      await onSave({ ...user, displayName, bio });
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to save profile");
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="profile-editor">
      <img src={user.avatarUrl} alt={`${user.displayName}'s avatar`} className="profile-editor__avatar" />

      <label className="profile-editor__field">
        <span>Display name</span>
        <input
          type="text"
          value={displayName}
          onChange={(e) => setDisplayName(e.target.value)}
          disabled={saving}
        />
      </label>

      <label className="profile-editor__field">
        <span>Bio</span>
        <textarea value={bio} onChange={(e) => setBio(e.target.value)} disabled={saving} />
      </label>

      <div className="profile-editor__status">
        {hasChanges ? "Unsaved changes" : "No unsaved changes"}
      </div>

      {error && <div className="profile-editor__error">{error}</div>}

      <div className="profile-editor__actions">
        <button type="button" onClick={handleReset} disabled={!hasChanges || saving}>
          Reset
        </button>
        <button type="button" onClick={handleSave} disabled={!hasChanges || saving}>
          {saving ? "Saving..." : "Save"}
        </button>
      </div>
    </div>
  );
}

import Foundation
import SwiftUI

struct Lap: Identifiable {
    let id = UUID()
    let number: Int
    let splitTime: TimeInterval
    let totalTime: TimeInterval
}

@MainActor
final class StopwatchViewModel: ObservableObject {
    @Published private(set) var elapsed: TimeInterval = 0
    @Published private(set) var laps: [Lap] = []
    @Published private(set) var isRunning = false

    private let clock = ContinuousClock()
    private var timer: Timer?
    private var startInstant: ContinuousClock.Instant?
    private var accumulated: TimeInterval = 0

    func start() {
        guard !isRunning else { return }
        isRunning = true
        startInstant = clock.now
        timer = Timer.scheduledTimer(withTimeInterval: 0.01, repeats: true) { [weak self] _ in
            Task { @MainActor in
                self?.tick()
            }
        }
    }

    func stop() {
        guard isRunning else { return }
        isRunning = false
        timer?.invalidate()
        timer = nil
        elapsed = currentElapsed()
        accumulated = elapsed
        startInstant = nil
    }

    func reset() {
        stop()
        elapsed = 0
        accumulated = 0
        laps = []
    }

    func lap() {
        guard isRunning else { return }
        elapsed = currentElapsed()
        let previousTotal = laps.last?.totalTime ?? 0
        laps.append(Lap(number: laps.count + 1, splitTime: elapsed - previousTotal, totalTime: elapsed))
    }

    private func tick() {
        elapsed = currentElapsed()
    }

    private func currentElapsed() -> TimeInterval {
        guard let startInstant else { return accumulated }
        return accumulated + (clock.now - startInstant).timeInterval
    }

    deinit {
        timer?.invalidate()
    }
}

private extension Duration {
    private static let attosecondsPerSecond: TimeInterval = 1e18

    var timeInterval: TimeInterval {
        TimeInterval(components.seconds) + TimeInterval(components.attoseconds) / Self.attosecondsPerSecond
    }
}

enum StopwatchFormatter {
    static func format(_ time: TimeInterval) -> String {
        let totalHundredths = Int((time * 100).rounded())
        let minutes = totalHundredths / 6000
        let seconds = (totalHundredths / 100) % 60
        let hundredths = totalHundredths % 100
        return String(format: "%02d:%02d.%02d", minutes, seconds, hundredths)
    }
}

struct StopwatchView: View {
    @StateObject private var viewModel = StopwatchViewModel()

    var body: some View {
        VStack(spacing: 24) {
            Text(StopwatchFormatter.format(viewModel.elapsed))
                .font(.system(size: 56, weight: .medium, design: .monospaced))
                .monospacedDigit()

            HStack(spacing: 16) {
                Button(viewModel.isRunning ? "Stop" : "Start") {
                    viewModel.isRunning ? viewModel.stop() : viewModel.start()
                }
                Button("Lap") {
                    viewModel.lap()
                }
                .disabled(!viewModel.isRunning)
                Button("Reset") {
                    viewModel.reset()
                }
                .disabled(viewModel.isRunning && viewModel.elapsed == 0)
            }
            .buttonStyle(.bordered)

            List {
                ForEach(viewModel.laps.reversed()) { lap in
                    HStack {
                        Text("Lap \(lap.number)")
                        Spacer()
                        Text(StopwatchFormatter.format(lap.splitTime))
                            .monospacedDigit()
                        Text(StopwatchFormatter.format(lap.totalTime))
                            .foregroundStyle(.secondary)
                            .monospacedDigit()
                    }
                }
            }
        }
        .padding()
    }
}

import SwiftUI

enum ThemeChoice: String, CaseIterable, Identifiable, Equatable {
    case system
    case light
    case dark

    var id: String { rawValue }

    var displayName: String {
        switch self {
        case .system: return "System"
        case .light: return "Light"
        case .dark: return "Dark"
        }
    }
}

@MainActor
final class SettingsStore: ObservableObject {
    private enum Keys {
        static let displayName = "settings.displayName"
        static let theme = "settings.theme"
        static let notificationsEnabled = "settings.notificationsEnabled"
        static let refreshInterval = "settings.refreshInterval"
    }

    static let defaultRefreshInterval: TimeInterval = 60
    static let refreshIntervalRange: ClosedRange<TimeInterval> = 15...3600

    @Published var displayName: String {
        didSet { persist { $0.set(displayName, forKey: Keys.displayName) } }
    }
    @Published var theme: ThemeChoice {
        didSet { persist { $0.set(theme.rawValue, forKey: Keys.theme) } }
    }
    @Published var notificationsEnabled: Bool {
        didSet { persist { $0.set(notificationsEnabled, forKey: Keys.notificationsEnabled) } }
    }
    @Published var refreshInterval: TimeInterval {
        didSet { persist { $0.set(refreshInterval, forKey: Keys.refreshInterval) } }
    }

    private let defaults: UserDefaults
    private var isApplyingExternalChange = false
    private var observer: NSObjectProtocol?

    init(defaults: UserDefaults = .standard) {
        self.defaults = defaults

        displayName = defaults.string(forKey: Keys.displayName) ?? ""
        theme = ThemeChoice(rawValue: defaults.string(forKey: Keys.theme) ?? "") ?? .system
        notificationsEnabled = defaults.object(forKey: Keys.notificationsEnabled) as? Bool ?? true
        refreshInterval = Self.sanitizedRefreshInterval(
            defaults.object(forKey: Keys.refreshInterval) as? TimeInterval
        )

        observer = NotificationCenter.default.addObserver(
            forName: UserDefaults.didChangeNotification,
            object: defaults,
            queue: .main
        ) { [weak self] _ in
            // queue: .main guarantees this runs on the main thread, matching the
            // store's actor isolation, even though the closure itself is nonisolated.
            MainActor.assumeIsolated {
                self?.reloadFromDefaults()
            }
        }
    }

    deinit {
        if let observer {
            NotificationCenter.default.removeObserver(observer)
        }
    }

    // Only writes to UserDefaults when the change originated locally (from the UI),
    // not when we're re-applying a value we just read back from an external change.
    private func persist(_ write: (UserDefaults) -> Void) {
        guard !isApplyingExternalChange else { return }
        write(defaults)
    }

    private func reloadFromDefaults() {
        isApplyingExternalChange = true
        defer { isApplyingExternalChange = false }

        let newDisplayName = defaults.string(forKey: Keys.displayName) ?? ""
        if newDisplayName != displayName { displayName = newDisplayName }

        let newTheme = ThemeChoice(rawValue: defaults.string(forKey: Keys.theme) ?? "") ?? .system
        if newTheme != theme { theme = newTheme }

        let newNotificationsEnabled = defaults.object(forKey: Keys.notificationsEnabled) as? Bool ?? true
        if newNotificationsEnabled != notificationsEnabled { notificationsEnabled = newNotificationsEnabled }

        let newRefreshInterval = Self.sanitizedRefreshInterval(
            defaults.object(forKey: Keys.refreshInterval) as? TimeInterval
        )
        if newRefreshInterval != refreshInterval { refreshInterval = newRefreshInterval }
    }

    // Guards against a malformed or out-of-range value in UserDefaults (e.g. edited
    // externally) producing NaN/infinity or a value outside the Stepper's bounds.
    private static func sanitizedRefreshInterval(_ value: TimeInterval?) -> TimeInterval {
        guard let value, value.isFinite else { return defaultRefreshInterval }
        return min(max(value, refreshIntervalRange.lowerBound), refreshIntervalRange.upperBound)
    }
}

struct SettingsScreen: View {
    @ObservedObject var store: SettingsStore

    var body: some View {
        Form {
            Section("Profile") {
                TextField("Display Name", text: $store.displayName)
            }

            Section("Appearance") {
                Picker("Theme", selection: $store.theme) {
                    ForEach(ThemeChoice.allCases) { theme in
                        Text(theme.displayName).tag(theme)
                    }
                }
            }

            Section("Notifications") {
                Toggle("Enable Notifications", isOn: $store.notificationsEnabled)
            }

            Section("Refresh") {
                Stepper(value: $store.refreshInterval, in: SettingsStore.refreshIntervalRange, step: 15) {
                    Text("Refresh Interval: \(Int(store.refreshInterval))s")
                }
            }
        }
        .padding()
        .navigationTitle("Settings")
    }
}

import { useEffect, useMemo, useState } from "react";

interface User {
  id: string;
  name: string;
  email: string;
}

type SortField = "name" | "email";

const DEBOUNCE_MS = 300;

function isUser(value: unknown): value is User {
  if (typeof value !== "object" || value === null) return false;
  const record = value as Record<string, unknown>;
  return (
    typeof record.id === "string" &&
    typeof record.name === "string" &&
    typeof record.email === "string"
  );
}

function parseUsers(value: unknown): User[] {
  if (!Array.isArray(value)) {
    throw new Error("Malformed response: expected an array of users");
  }
  if (!value.every(isUser)) {
    throw new Error("Malformed response: unexpected user shape");
  }
  return value;
}

function isSortField(value: string): value is SortField {
  return value === "name" || value === "email";
}

export default function UserSearch() {
  const [query, setQuery] = useState("");
  const [debouncedQuery, setDebouncedQuery] = useState("");
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [sortField, setSortField] = useState<SortField>("name");

  useEffect(() => {
    const timer = setTimeout(() => setDebouncedQuery(query), DEBOUNCE_MS);
    return () => clearTimeout(timer);
  }, [query]);

  useEffect(() => {
    if (!debouncedQuery) {
      setUsers([]);
      setError(null);
      setLoading(false);
      return;
    }

    const controller = new AbortController();
    let isCurrent = true;
    setLoading(true);
    setError(null);

    fetch(`/api/users?q=${encodeURIComponent(debouncedQuery)}`, {
      signal: controller.signal,
    })
      .then((res) => {
        if (!res.ok) {
          throw new Error(`Request failed with status ${res.status}`);
        }
        return res.json();
      })
      .then((json: unknown) => {
        if (!isCurrent) return;
        setUsers(parseUsers(json));
        setLoading(false);
      })
      .catch((err: unknown) => {
        if (!isCurrent) return;
        if (err instanceof DOMException && err.name === "AbortError") {
          return;
        }
        setError(err instanceof Error ? err.message : "Failed to fetch users");
        setUsers([]);
        setLoading(false);
      });

    return () => {
      isCurrent = false;
      controller.abort();
    };
  }, [debouncedQuery]);

  const sortedUsers = useMemo(() => {
    return [...users].sort((a, b) => a[sortField].localeCompare(b[sortField]));
  }, [users, sortField]);

  const isDebouncePending = query !== debouncedQuery;

  return (
    <div>
      <input
        type="text"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Search users..."
        aria-label="Search users"
      />

      <div>
        <label>
          Sort by:{" "}
          <select
            value={sortField}
            onChange={(e) => {
              if (isSortField(e.target.value)) {
                setSortField(e.target.value);
              }
            }}
          >
            <option value="name">Name</option>
            <option value="email">Email</option>
          </select>
        </label>
      </div>

      {(loading || isDebouncePending) && <p>Loading...</p>}
      {error && <p role="alert">Error: {error}</p>}
      {!loading && !isDebouncePending && !error && debouncedQuery && (
        <p>
          {sortedUsers.length} result{sortedUsers.length === 1 ? "" : "s"}
        </p>
      )}

      {!isDebouncePending && (
        <ul>
          {sortedUsers.map((user) => (
            <li key={user.id}>
              {user.name} ({user.email})
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

import Foundation

// MARK: - Legacy SDK (callback-based)

private let stubGeocodeDelay: TimeInterval = 0.1
private let stubUploadStepCount = 5
private let stubUploadStepDelay: TimeInterval = 0.05

final class LegacyGeocoder {
    func geocode(_ address: String, completion: @escaping (Result<(Double, Double), Error>) -> Void) {
        DispatchQueue.global().asyncAfter(deadline: .now() + stubGeocodeDelay) {
            completion(.success((37.7749, -122.4194)))
        }
    }
}

final class LegacyUploader {
    var onProgress: ((Double) -> Void)?
    var onFinish: ((Error?) -> Void)?

    private let lock = NSLock()
    private var isCancelled = false

    func start(file: URL) {
        for step in 1...stubUploadStepCount {
            DispatchQueue.global().asyncAfter(deadline: .now() + Double(step) * stubUploadStepDelay) {
                self.lock.lock()
                let cancelled = self.isCancelled
                self.lock.unlock()
                guard !cancelled else { return }
                self.onProgress?(Double(step) / Double(stubUploadStepCount))
                if step == stubUploadStepCount {
                    self.onFinish?(nil)
                }
            }
        }
    }

    /// Stops future scheduled callbacks from firing. The legacy SDK has no real
    /// cancellation hook, so this is best-effort: it only suppresses steps that
    /// haven't fired yet.
    func cancel() {
        lock.lock()
        isCancelled = true
        lock.unlock()
    }
}

// MARK: - Modern async/await bridge

enum LegacyBridgeError: Error {
    case uploadAlreadyInProgress
}

/// Delivers a single result to a `CheckedContinuation` exactly once, even if
/// the wrapped callback API fires more than once or a cancellation handler
/// races with attaching the continuation.
private final class ContinuationBridge<T> {
    private let lock = NSLock()
    private var continuation: CheckedContinuation<T, Error>?
    private var bufferedResult: Result<T, Error>?

    func attach(_ continuation: CheckedContinuation<T, Error>) {
        lock.lock()
        if let bufferedResult {
            lock.unlock()
            continuation.resume(with: bufferedResult)
            return
        }
        self.continuation = continuation
        lock.unlock()
    }

    func resume(with result: Result<T, Error>) {
        lock.lock()
        guard bufferedResult == nil else {
            lock.unlock()
            return
        }
        bufferedResult = result
        let pending = continuation
        continuation = nil
        lock.unlock()
        pending?.resume(with: result)
    }
}

final class LegacyGeocoderBridge {
    private let geocoder = LegacyGeocoder()

    func geocode(_ address: String) async throws -> (Double, Double) {
        let bridge = ContinuationBridge<(Double, Double)>()
        return try await withTaskCancellationHandler {
            try await withCheckedThrowingContinuation { continuation in
                bridge.attach(continuation)
                geocoder.geocode(address) { result in
                    bridge.resume(with: result)
                }
            }
        } onCancel: {
            bridge.resume(with: .failure(CancellationError()))
        }
    }
}

final class LegacyUploaderBridge {
    private let uploader = LegacyUploader()

    /// Emits progress values as the upload runs; finishes when the upload completes or fails.
    let progress: AsyncStream<Double>
    private let progressContinuation: AsyncStream<Double>.Continuation

    private let lock = NSLock()
    private var isUploading = false

    init() {
        (progress, progressContinuation) = AsyncStream.makeStream(of: Double.self)
    }

    private func beginUpload() throws {
        lock.lock()
        defer { lock.unlock() }
        guard !isUploading else {
            throw LegacyBridgeError.uploadAlreadyInProgress
        }
        isUploading = true
    }

    private func endUpload() {
        lock.lock()
        defer { lock.unlock() }
        isUploading = false
    }

    func upload(file: URL) async throws {
        try beginUpload()
        defer { endUpload() }

        let bridge = ContinuationBridge<Void>()
        uploader.onProgress = { [progressContinuation] value in
            progressContinuation.yield(value)
        }

        try await withTaskCancellationHandler {
            try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in
                bridge.attach(continuation)
                uploader.onFinish = { [progressContinuation] error in
                    progressContinuation.finish()
                    let result: Result<Void, Error> = error.map { .failure($0) } ?? .success(())
                    bridge.resume(with: result)
                }
                uploader.start(file: file)
            }
        } onCancel: {
            uploader.cancel()
            progressContinuation.finish()
            bridge.resume(with: .failure(CancellationError()))
        }
    }
}

import Foundation
import SwiftUI

struct ChatMessage: Codable, Identifiable, Hashable {
    let id: String
    let author: String
    let text: String
}

@MainActor
final class ChatConnection: NSObject, ObservableObject {
    @Published private(set) var messages: [ChatMessage] = []

    private let url = URL(string: "wss://chat.example.com/room")!
    private var session: URLSession!
    private var task: URLSessionWebSocketTask?
    private var reconnectDelay: TimeInterval = 1
    private let maxReconnectDelay: TimeInterval = 30
    private var shouldReconnect = true
    private let maxMessages = 500

    /// Bumped on every connect/stop/reconnect so callbacks and delayed reconnects
    /// from a superseded connection attempt can recognize they're stale and no-op.
    private var generation = 0

    override init() {
        super.init()
        session = URLSession(configuration: .default)
    }

    func start() {
        shouldReconnect = true
        generation += 1
        task?.cancel(with: .goingAway, reason: nil)
        task = nil
        reconnectDelay = 1
        connect()
    }

    func stop() {
        shouldReconnect = false
        generation += 1
        task?.cancel(with: .goingAway, reason: nil)
        task = nil
    }

    @discardableResult
    func send(text: String) -> Bool {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return false }
        guard let task, task.state == .running else { return false }
        let message = ChatMessage(id: UUID().uuidString, author: "me", text: trimmed)
        guard let data = try? JSONEncoder().encode(message) else { return false }
        let sendGeneration = generation
        task.send(.data(data)) { [weak self] error in
            guard error != nil else { return }
            Task { @MainActor in
                guard let self, self.generation == sendGeneration else { return }
                self.handleDisconnect(generation: sendGeneration)
            }
        }
        return true
    }

    private func connect() {
        let connectGeneration = generation
        let task = session.webSocketTask(with: url)
        self.task = task
        task.resume()
        listen(on: task, generation: connectGeneration)
    }

    private func listen(on task: URLSessionWebSocketTask, generation: Int) {
        task.receive { [weak self] result in
            guard let self else { return }
            Task { @MainActor in
                guard self.generation == generation else { return }
                switch result {
                case .failure:
                    self.handleDisconnect(generation: generation)
                case .success(let message):
                    self.reconnectDelay = 1
                    self.handle(message)
                    self.listen(on: task, generation: generation)
                }
            }
        }
    }

    private func handle(_ message: URLSessionWebSocketTask.Message) {
        let data: Data
        switch message {
        case .data(let d):
            data = d
        case .string(let s):
            data = Data(s.utf8)
        @unknown default:
            return
        }
        guard let chatMessage = try? JSONDecoder().decode(ChatMessage.self, from: data) else { return }
        messages.append(chatMessage)
        if messages.count > maxMessages {
            messages.removeFirst(messages.count - maxMessages)
        }
    }

    private func handleDisconnect(generation: Int) {
        guard self.generation == generation else { return }
        task = nil
        guard shouldReconnect else { return }
        let delay = reconnectDelay
        reconnectDelay = min(reconnectDelay * 2, maxReconnectDelay)
        DispatchQueue.main.asyncAfter(deadline: .now() + delay) { [weak self] in
            guard let self, self.shouldReconnect, self.generation == generation else { return }
            self.connect()
        }
    }
}

struct ChatScreen: View {
    @StateObject private var connection = ChatConnection()
    @State private var draft = ""

    var body: some View {
        VStack(spacing: 0) {
            ScrollViewReader { proxy in
                ScrollView {
                    LazyVStack(alignment: .leading, spacing: 8) {
                        ForEach(connection.messages) { message in
                            VStack(alignment: .leading, spacing: 2) {
                                Text(message.author)
                                    .font(.caption)
                                    .foregroundStyle(.secondary)
                                Text(message.text)
                            }
                            .id(message.id)
                            .padding(.horizontal)
                        }
                    }
                    .padding(.vertical, 8)
                }
                .onChange(of: connection.messages) { messages in
                    guard let last = messages.last else { return }
                    withAnimation {
                        proxy.scrollTo(last.id, anchor: .bottom)
                    }
                }
            }

            Divider()

            HStack {
                TextField("Message", text: $draft)
                    .textFieldStyle(.roundedBorder)
                    .onSubmit(sendDraft)
                Button("Send", action: sendDraft)
                    .disabled(draft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
            }
            .padding()
        }
        .onAppear { connection.start() }
        .onDisappear { connection.stop() }
    }

    private func sendDraft() {
        guard connection.send(text: draft) else { return }
        draft = ""
    }
}

import SwiftUI

#if canImport(UIKit)
import UIKit
typealias PlatformImage = UIImage
#elseif canImport(AppKit)
import AppKit
typealias PlatformImage = NSImage
#endif

struct Photo: Identifiable, Hashable {
    let id = UUID()
    let url: URL
    let downloadDate: Date
}

/// In-memory cache shared across all thumbnails so scrolling back into
/// view doesn't trigger a re-download. Isolated as an actor so concurrent
/// loads from multiple thumbnails can't race on the underlying cache.
/// In-flight downloads are tracked so concurrent misses for the same URL
/// share one download+decode instead of each starting their own, and the
/// decode itself runs off the main actor via a detached task.
actor ImageCache {
    static let shared = ImageCache()

    private let cache = NSCache<NSURL, PlatformImage>()
    private var inFlightTasks: [URL: Task<PlatformImage?, Never>] = [:]

    private init() {}

    func image(for url: URL) async -> PlatformImage? {
        if let cached = cache.object(forKey: url as NSURL) {
            return cached
        }

        if let existing = inFlightTasks[url] {
            return await existing.value
        }

        let task = Task.detached { () -> PlatformImage? in
            guard let (data, _) = try? await URLSession.shared.data(from: url) else {
                return nil
            }
            return PlatformImage(data: data)
        }
        inFlightTasks[url] = task

        let result = await task.value
        inFlightTasks[url] = nil

        if let result {
            cache.setObject(result, forKey: url as NSURL)
        }
        return result
    }
}

private struct ThumbnailView: View {
    let url: URL

    @State private var image: PlatformImage?
    @State private var loadFailed = false

    var body: some View {
        ZStack {
            if let image {
                platformImage(image)
                    .resizable()
                    .aspectRatio(contentMode: .fill)
            } else if loadFailed {
                Rectangle()
                    .fill(Color.secondary.opacity(0.2))
                    .overlay {
                        Button {
                            loadFailed = false
                            Task { await loadImage(for: url) }
                        } label: {
                            Image(systemName: "arrow.clockwise")
                        }
                        .buttonStyle(.plain)
                    }
            } else {
                Rectangle()
                    .fill(Color.secondary.opacity(0.2))
                    .overlay(ProgressView())
            }
        }
        .task(id: url) {
            image = nil
            loadFailed = false
            await loadImage(for: url)
        }
    }

    @ViewBuilder
    private func platformImage(_ image: PlatformImage) -> Image {
        #if canImport(UIKit)
        Image(uiImage: image)
        #else
        Image(nsImage: image)
        #endif
    }

    @MainActor
    private func loadImage(for url: URL) async {
        let result = await ImageCache.shared.image(for: url)

        // The URL-keyed task may have been cancelled (e.g. url changed again)
        // while suspended on the actor call; don't publish a stale result.
        guard !Task.isCancelled else { return }

        if let result {
            image = result
        } else {
            loadFailed = true
        }
    }
}

struct ThumbnailGrid: View {
    let photos: [Photo]

    private let columns = [GridItem(.adaptive(minimum: 100), spacing: 8)]

    var body: some View {
        ScrollView {
            LazyVGrid(columns: columns, spacing: 8) {
                ForEach(photos) { photo in
                    VStack(alignment: .leading, spacing: 4) {
                        ThumbnailView(url: photo.url)
                            .frame(height: 100)
                            .clipped()
                            .cornerRadius(8)

                        Text(photo.downloadDate, style: .relative)
                            .font(.caption)
                            .foregroundStyle(.secondary)
                    }
                }
            }
            .padding()
        }
    }
}

import { useEffect, useRef, useState, type FormEvent } from "react";

interface ChatMessage {
  id: string;
  author: string;
  text: string;
  sentAt: string;
}

function isChatMessage(value: unknown): value is ChatMessage {
  if (typeof value !== "object" || value === null) return false;
  const v = value as Record<string, unknown>;
  return (
    typeof v.id === "string" &&
    typeof v.author === "string" &&
    typeof v.text === "string" &&
    typeof v.sentAt === "string" &&
    !Number.isNaN(Date.parse(v.sentAt))
  );
}

const RECONNECT_DELAY_MS = 2000;

export interface ChatRoomProps {
  roomId: string;
}

export function ChatRoom({ roomId }: ChatRoomProps) {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [draft, setDraft] = useState("");
  const [isReconnecting, setIsReconnecting] = useState(false);

  const socketRef = useRef<WebSocket | null>(null);
  const messagesEndRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    setMessages([]);
    setIsReconnecting(false);

    let cancelled = false;
    let reconnectTimer: ReturnType<typeof setTimeout> | undefined;
    let socket: WebSocket | undefined;

    const connect = () => {
      if (cancelled) return;

      socket = new WebSocket(
        `wss://chat.example.com/rooms/${encodeURIComponent(roomId)}`,
      );
      socketRef.current = socket;

      socket.addEventListener("open", () => {
        if (cancelled) return;
        setIsReconnecting(false);
      });

      socket.addEventListener("message", (event: MessageEvent) => {
        if (cancelled) return;
        try {
          const parsed: unknown = JSON.parse(event.data as string);
          if (isChatMessage(parsed)) {
            setMessages((prev) => [...prev, parsed]);
          }
        } catch (error) {
          console.error("Failed to parse chat message", error);
        }
      });

      socket.addEventListener("close", () => {
        if (cancelled) return;
        setIsReconnecting(true);
        reconnectTimer = setTimeout(connect, RECONNECT_DELAY_MS);
      });

      socket.addEventListener("error", (event) => {
        (event.target as WebSocket).close();
      });
    };

    connect();

    return () => {
      cancelled = true;
      if (reconnectTimer !== undefined) clearTimeout(reconnectTimer);
      socketRef.current = null;
      socket?.close();
    };
  }, [roomId]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const text = draft.trim();
    const socket = socketRef.current;
    if (!text || !socket || socket.readyState !== WebSocket.OPEN) return;

    socket.send(JSON.stringify({ text }));
    setDraft("");
  };

  return (
    <div className="chat-room">
      {isReconnecting && (
        <div className="chat-room__banner" role="status">
          Reconnecting…
        </div>
      )}

      <div className="chat-room__messages">
        {messages.map((message) => (
          <div key={message.id} className="chat-room__message">
            <span className="chat-room__author">{message.author}</span>
            <span className="chat-room__text">{message.text}</span>
            <span className="chat-room__time">
              {new Date(message.sentAt).toLocaleTimeString()}
            </span>
          </div>
        ))}
        <div ref={messagesEndRef} />
      </div>

      <form className="chat-room__composer" onSubmit={handleSubmit}>
        <input
          type="text"
          value={draft}
          onChange={(event) => setDraft(event.target.value)}
          placeholder="Type a message…"
        />
        <button type="submit">Send</button>
      </form>
    </div>
  );
}

export default ChatRoom;

import { useState, FormEvent, useRef } from "react";

interface FormState {
  name: string;
  email: string;
  password: string;
  confirmPassword: string;
  acceptTerms: boolean;
}

type FieldErrors = Partial<Record<keyof FormState, string>>;

const initialState: FormState = {
  name: "",
  email: "",
  password: "",
  confirmPassword: "",
  acceptTerms: false,
};

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function validate(form: FormState): FieldErrors {
  const errors: FieldErrors = {};

  if (!form.name.trim()) {
    errors.name = "Name is required.";
  }

  if (!form.email.trim()) {
    errors.email = "Email is required.";
  } else if (!EMAIL_PATTERN.test(form.email)) {
    errors.email = "Enter a valid email address.";
  }

  if (!form.password) {
    errors.password = "Password is required.";
  } else if (form.password.length < 8) {
    errors.password = "Password must be at least 8 characters.";
  }

  if (!form.confirmPassword) {
    errors.confirmPassword = "Please confirm your password.";
  } else if (form.confirmPassword !== form.password) {
    errors.confirmPassword = "Passwords do not match.";
  }

  if (!form.acceptTerms) {
    errors.acceptTerms = "You must accept the terms to continue.";
  }

  return errors;
}

interface SignupSuccessResponse {
  id: string;
}

interface SignupErrorResponse {
  errors: Partial<Record<keyof FormState, string>>;
}

const FORM_FIELDS: readonly (keyof FormState)[] = [
  "name",
  "email",
  "password",
  "confirmPassword",
  "acceptTerms",
];

function isSignupErrorResponse(payload: unknown): payload is SignupErrorResponse {
  if (typeof payload !== "object" || payload === null || Array.isArray(payload)) {
    return false;
  }
  if (!("errors" in payload)) {
    return false;
  }
  const errors = (payload as { errors: unknown }).errors;
  if (typeof errors !== "object" || errors === null || Array.isArray(errors)) {
    return false;
  }
  return Object.entries(errors).every(
    ([field, message]) =>
      FORM_FIELDS.includes(field as keyof FormState) &&
      (message === undefined || typeof message === "string")
  );
}

function isSignupSuccessResponse(payload: unknown): payload is SignupSuccessResponse {
  return (
    typeof payload === "object" &&
    payload !== null &&
    "id" in payload &&
    typeof (payload as { id: unknown }).id === "string"
  );
}

export default function SignupForm() {
  const [form, setForm] = useState<FormState>(initialState);
  const [errors, setErrors] = useState<FieldErrors>({});
  const [submitting, setSubmitting] = useState(false);
  const [formError, setFormError] = useState<string | null>(null);
  const [accountId, setAccountId] = useState<string | null>(null);
  const submittingRef = useRef(false);

  function updateField<K extends keyof FormState>(field: K, value: FormState[K]) {
    setForm((prev) => ({ ...prev, [field]: value }));
    setErrors((prev) => ({ ...prev, [field]: undefined }));
  }

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (submittingRef.current) {
      return;
    }
    setFormError(null);
    setAccountId(null);

    const clientErrors = validate(form);
    if (Object.keys(clientErrors).length > 0) {
      setErrors(clientErrors);
      return;
    }

    submittingRef.current = true;
    setSubmitting(true);
    try {
      const response = await fetch("/api/signup", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: form.name,
          email: form.email,
          password: form.password,
          confirmPassword: form.confirmPassword,
          acceptTerms: form.acceptTerms,
        }),
      });

      const responseBody: unknown = await response.json().catch(() => null);

      if (!response.ok) {
        if (isSignupErrorResponse(responseBody)) {
          setErrors(responseBody.errors);
        } else {
          setFormError("Sign up failed. Please try again.");
        }
        return;
      }

      if (!isSignupSuccessResponse(responseBody)) {
        setFormError("Sign up failed. Please try again.");
        return;
      }

      setAccountId(responseBody.id);
      setForm(initialState);
      setErrors({});
      setFormError(null);
    } catch {
      setFormError("Sign up failed. Please check your connection and try again.");
    } finally {
      submittingRef.current = false;
      setSubmitting(false);
    }
  }

  return (
    <form onSubmit={handleSubmit} noValidate>
      <h1>Create an account</h1>

      {accountId && (
        <p role="status">Account created successfully! Your account id is {accountId}.</p>
      )}
      {formError && <p role="alert">{formError}</p>}

      <fieldset disabled={submitting} style={{ border: "none", padding: 0, margin: 0 }}>
      <div>
        <label htmlFor="name">Name</label>
        <input
          id="name"
          type="text"
          value={form.name}
          onChange={(e) => updateField("name", e.target.value)}
          aria-invalid={Boolean(errors.name)}
          aria-describedby={errors.name ? "name-error" : undefined}
        />
        {errors.name && <p id="name-error">{errors.name}</p>}
      </div>

      <div>
        <label htmlFor="email">Email</label>
        <input
          id="email"
          type="email"
          value={form.email}
          onChange={(e) => updateField("email", e.target.value)}
          aria-invalid={Boolean(errors.email)}
          aria-describedby={errors.email ? "email-error" : undefined}
        />
        {errors.email && <p id="email-error">{errors.email}</p>}
      </div>

      <div>
        <label htmlFor="password">Password</label>
        <input
          id="password"
          type="password"
          value={form.password}
          onChange={(e) => updateField("password", e.target.value)}
          aria-invalid={Boolean(errors.password)}
          aria-describedby={errors.password ? "password-error" : undefined}
        />
        {errors.password && <p id="password-error">{errors.password}</p>}
      </div>

      <div>
        <label htmlFor="confirmPassword">Confirm password</label>
        <input
          id="confirmPassword"
          type="password"
          value={form.confirmPassword}
          onChange={(e) => updateField("confirmPassword", e.target.value)}
          aria-invalid={Boolean(errors.confirmPassword)}
          aria-describedby={errors.confirmPassword ? "confirmPassword-error" : undefined}
        />
        {errors.confirmPassword && <p id="confirmPassword-error">{errors.confirmPassword}</p>}
      </div>

      <div>
        <label htmlFor="acceptTerms">
          <input
            id="acceptTerms"
            type="checkbox"
            checked={form.acceptTerms}
            onChange={(e) => updateField("acceptTerms", e.target.checked)}
            aria-invalid={Boolean(errors.acceptTerms)}
            aria-describedby={errors.acceptTerms ? "acceptTerms-error" : undefined}
          />
          I accept the terms and conditions
        </label>
        {errors.acceptTerms && <p id="acceptTerms-error">{errors.acceptTerms}</p>}
      </div>
      </fieldset>

      <button type="submit" disabled={submitting}>
        {submitting ? "Signing up..." : "Sign up"}
      </button>
    </form>
  );
}

import { useCallback, useEffect, useRef, useState } from "react";

interface Metric {
  name: string;
  value: number;
  unit: string;
}

const POLL_INTERVAL_MS = 10_000;
const TICK_INTERVAL_MS = 1_000;

function isMetric(value: unknown): value is Metric {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.name === "string" &&
    typeof candidate.value === "number" &&
    Number.isFinite(candidate.value) &&
    typeof candidate.unit === "string"
  );
}

function isMetricArray(data: unknown): data is Metric[] {
  return Array.isArray(data) && data.every(isMetric);
}

function dedupeByName(metrics: Metric[]): Metric[] {
  const seen = new Set<string>();
  const result: Metric[] = [];
  for (const metric of metrics) {
    if (seen.has(metric.name)) continue;
    seen.add(metric.name);
    result.push(metric);
  }
  return result;
}

export default function MetricsPanel() {
  const [metrics, setMetrics] = useState<Metric[]>([]);
  const [changedNames, setChangedNames] = useState<Set<string>>(new Set());
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [now, setNow] = useState(() => Date.now());

  const previousValuesRef = useRef<Map<string, number>>(new Map());
  const inFlightRef = useRef<AbortController | null>(null);

  const fetchMetrics = useCallback(async () => {
    inFlightRef.current?.abort();
    const controller = new AbortController();
    inFlightRef.current = controller;

    try {
      const res = await fetch("/api/metrics", { signal: controller.signal });
      if (!res.ok) throw new Error(`Request failed: ${res.status}`);
      const data: unknown = await res.json();
      if (inFlightRef.current !== controller) return;
      if (!isMetricArray(data)) throw new Error("Unexpected metrics response shape");

      const uniqueData = dedupeByName(data);

      const previousValues = previousValuesRef.current;
      const nextChanged = new Set<string>();
      for (const metric of uniqueData) {
        const prev = previousValues.get(metric.name);
        if (prev !== undefined && prev !== metric.value) {
          nextChanged.add(metric.name);
        }
      }

      previousValuesRef.current = new Map(uniqueData.map((m) => [m.name, m.value]));
      setMetrics(uniqueData);
      setChangedNames(nextChanged);
      setLastUpdated(new Date());
      setError(null);
    } catch (err) {
      if (err instanceof DOMException && err.name === "AbortError") return;
      if (inFlightRef.current !== controller) return;
      setError(err instanceof Error ? err.message : "Failed to load metrics");
    }
  }, []);

  useEffect(() => {
    let timeoutId: ReturnType<typeof setTimeout> | null = null;
    let cancelled = false;

    const stopPolling = () => {
      if (timeoutId === null) return;
      clearTimeout(timeoutId);
      timeoutId = null;
    };

    const scheduleNext = () => {
      if (cancelled || document.hidden) return;
      timeoutId = setTimeout(runPoll, POLL_INTERVAL_MS);
    };

    const runPoll = () => {
      fetchMetrics().then(scheduleNext);
    };

    const handleVisibilityChange = () => {
      if (document.hidden) {
        stopPolling();
      } else {
        stopPolling();
        runPoll();
      }
    };

    runPoll();

    document.addEventListener("visibilitychange", handleVisibilityChange);

    return () => {
      cancelled = true;
      stopPolling();
      inFlightRef.current?.abort();
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, [fetchMetrics]);

  useEffect(() => {
    if (!lastUpdated) return;
    const tickId = setInterval(() => setNow(Date.now()), TICK_INTERVAL_MS);
    return () => clearInterval(tickId);
  }, [lastUpdated]);

  const secondsAgo = lastUpdated ? Math.max(0, Math.floor((now - lastUpdated.getTime()) / 1000)) : null;

  return (
    <div className="metrics-panel">
      <header className="metrics-panel__header">
        <h2>Metrics</h2>
        {secondsAgo !== null && (
          <span className="metrics-panel__updated">
            Last updated {secondsAgo} second{secondsAgo === 1 ? "" : "s"} ago
          </span>
        )}
      </header>

      {error && <div className="metrics-panel__error">{error}</div>}

      <ul className="metrics-panel__list">
        {metrics.map((metric) => (
          <li
            key={metric.name}
            className={
              changedNames.has(metric.name)
                ? "metrics-panel__item metrics-panel__item--changed"
                : "metrics-panel__item"
            }
          >
            <span className="metrics-panel__name">{metric.name}</span>
            <span className="metrics-panel__value">
              {metric.value} {metric.unit}
            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useEffect, useState } from "react";
import type { UserProfile } from "./ProfileEditor";

export interface UseUserProfilesResult {
  profiles: Record<string, UserProfile>;
  errors: Record<string, string>;
  loading: boolean;
}

function isUserProfile(value: unknown): value is UserProfile {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.id === "string" &&
    typeof candidate.displayName === "string" &&
    typeof candidate.bio === "string" &&
    typeof candidate.avatarUrl === "string"
  );
}

export function useUserProfiles(ids: string[]): UseUserProfilesResult {
  const [profiles, setProfiles] = useState<Record<string, UserProfile>>({});
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(ids.length > 0);

  const idsKey = JSON.stringify(ids);

  useEffect(() => {
    const currentIds: string[] = JSON.parse(idsKey);
    if (currentIds.length === 0) {
      setProfiles({});
      setErrors({});
      setLoading(false);
      return;
    }

    const controller = new AbortController();
    setLoading(true);
    setProfiles({});
    setErrors({});

    Promise.all(
      currentIds.map(async (id) => {
        try {
          const response = await fetch(
            `/api/users/${encodeURIComponent(id)}`,
            { signal: controller.signal }
          );
          if (!response.ok) {
            throw new Error(`Failed to load user ${id}: ${response.status}`);
          }
          const rawProfile: unknown = await response.json();
          if (!isUserProfile(rawProfile)) {
            throw new Error(`Malformed profile data for user ${id}`);
          }
          if (rawProfile.id !== id) {
            throw new Error(`Received profile for wrong user (expected ${id}, got ${rawProfile.id})`);
          }
          setProfiles((prev) => ({ ...prev, [id]: rawProfile }));
        } catch (err) {
          if (controller.signal.aborted) return;
          const message =
            err instanceof Error ? err.message : `Failed to load user ${id}`;
          setErrors((prev) => ({ ...prev, [id]: message }));
        }
      })
    ).then(() => {
      if (!controller.signal.aborted) {
        setLoading(false);
      }
    });

    return () => controller.abort();
  }, [idsKey]);

  return { profiles, errors, loading };
}

import { useId, useState } from "react";

export interface UserProfile {
  id: string;
  displayName: string;
  bio: string;
  avatarUrl: string;
}

export interface ProfileEditorProps {
  user: UserProfile;
  onSave: (user: UserProfile) => Promise<void>;
}

export function ProfileEditor({ user, onSave }: ProfileEditorProps) {
  const idPrefix = useId();
  const [displayName, setDisplayName] = useState(user.displayName);
  const [bio, setBio] = useState(user.bio);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [syncedUserId, setSyncedUserId] = useState(user.id);

  if (user.id !== syncedUserId) {
    setSyncedUserId(user.id);
    setDisplayName(user.displayName);
    setBio(user.bio);
    setError(null);
  }

  const hasUnsavedChanges =
    displayName !== user.displayName || bio !== user.bio;

  const handleReset = () => {
    setDisplayName(user.displayName);
    setBio(user.bio);
    setError(null);
  };

  const handleSave = async () => {
    if (isSaving) return;
    setIsSaving(true);
    setError(null);
    try {
      await onSave({ ...user, displayName, bio });
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to save profile");
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        void handleSave();
      }}
    >
      <img src={user.avatarUrl} alt={`${user.displayName}'s avatar`} />

      <label htmlFor={`${idPrefix}-displayName`}>Display name</label>
      <input
        id={`${idPrefix}-displayName`}
        type="text"
        value={displayName}
        onChange={(event) => setDisplayName(event.target.value)}
        disabled={isSaving}
      />

      <label htmlFor={`${idPrefix}-bio`}>Bio</label>
      <textarea
        id={`${idPrefix}-bio`}
        value={bio}
        onChange={(event) => setBio(event.target.value)}
        disabled={isSaving}
      />

      <p>{hasUnsavedChanges ? "You have unsaved changes." : "All changes saved."}</p>
      {error && <p role="alert">{error}</p>}

      <button type="submit" disabled={isSaving || !hasUnsavedChanges}>
        {isSaving ? "Saving..." : "Save"}
      </button>
      <button
        type="button"
        onClick={handleReset}
        disabled={isSaving || !hasUnsavedChanges}
      >
        Reset
      </button>
    </form>
  );
}

import Foundation
import SwiftUI

struct Lap: Identifiable {
    let id: Int
    let splitTime: TimeInterval
    let totalTime: TimeInterval
}

final class StopwatchViewModel: ObservableObject {
    @Published private(set) var elapsedTime: TimeInterval = 0
    @Published private(set) var laps: [Lap] = []
    @Published private(set) var isRunning = false

    private var timer: Timer?
    private var startUptime: TimeInterval?

    deinit {
        timer?.invalidate()
    }

    func start() {
        guard !isRunning else { return }
        isRunning = true
        startUptime = ProcessInfo.processInfo.systemUptime - elapsedTime
        timer = Timer.scheduledTimer(withTimeInterval: 0.01, repeats: true) { [weak self] _ in
            self?.tick()
        }
    }

    func stop() {
        guard isRunning else { return }
        tick()
        isRunning = false
        timer?.invalidate()
        timer = nil
    }

    func reset() {
        stop()
        elapsedTime = 0
        laps = []
    }

    func lap() {
        guard isRunning else { return }
        tick()
        let previousTotal = laps.last?.totalTime ?? 0
        let split = elapsedTime - previousTotal
        laps.append(Lap(id: laps.count + 1, splitTime: split, totalTime: elapsedTime))
    }

    private func tick() {
        guard let startUptime else { return }
        elapsedTime = ProcessInfo.processInfo.systemUptime - startUptime
    }
}

enum TimeFormatter {
    static func format(_ time: TimeInterval) -> String {
        let totalHundredths = Int((time * 100).rounded())
        let minutes = totalHundredths / 6000
        let seconds = (totalHundredths / 100) % 60
        let hundredths = totalHundredths % 100
        return String(format: "%02d:%02d.%02d", minutes, seconds, hundredths)
    }
}

struct StopwatchView: View {
    @StateObject private var viewModel = StopwatchViewModel()

    var body: some View {
        VStack(spacing: 24) {
            Text(TimeFormatter.format(viewModel.elapsedTime))
                .font(.system(size: 56, weight: .medium, design: .monospaced))

            HStack(spacing: 16) {
                Button(viewModel.isRunning ? "Stop" : "Start") {
                    viewModel.isRunning ? viewModel.stop() : viewModel.start()
                }
                Button("Lap") {
                    viewModel.lap()
                }
                .disabled(!viewModel.isRunning)

                Button("Reset") {
                    viewModel.reset()
                }
                .disabled(!viewModel.isRunning && viewModel.elapsedTime == 0)
            }
            .buttonStyle(.bordered)

            List(viewModel.laps.reversed()) { lap in
                HStack {
                    Text("Lap \(lap.id)")
                    Spacer()
                    Text(TimeFormatter.format(lap.splitTime))
                        .font(.system(.body, design: .monospaced))
                    Spacer()
                    Text(TimeFormatter.format(lap.totalTime))
                        .font(.system(.body, design: .monospaced))
                        .foregroundStyle(.secondary)
                }
            }
        }
        .padding()
    }
}

import Combine
import Foundation
import SwiftUI

enum AppTheme: String, CaseIterable, Identifiable, Codable {
    case system
    case light
    case dark

    var id: String { rawValue }

    var displayName: String {
        switch self {
        case .system: return "System"
        case .light: return "Light"
        case .dark: return "Dark"
        }
    }
}

/// Persists user preferences to UserDefaults and stays in sync if they
/// change from elsewhere (e.g. another window, or a sync process).
///
/// Confined to the main actor: UserDefaults.didChangeNotification can be
/// posted from any thread, and @Published mutations must happen on main.
@MainActor
final class SettingsStore: ObservableObject {
    private enum Keys {
        static let displayName = "settings.displayName"
        static let theme = "settings.theme"
        static let notificationsEnabled = "settings.notificationsEnabled"
        static let refreshInterval = "settings.refreshInterval"
    }

    @Published var displayName: String {
        didSet { persist(displayName, forKey: Keys.displayName) }
    }
    @Published var theme: AppTheme {
        didSet { persist(theme.rawValue, forKey: Keys.theme) }
    }
    @Published var notificationsEnabled: Bool {
        didSet { persist(notificationsEnabled, forKey: Keys.notificationsEnabled) }
    }
    @Published var refreshInterval: TimeInterval {
        didSet { persist(refreshInterval, forKey: Keys.refreshInterval) }
    }

    private let defaults: UserDefaults
    // Guards against re-writing values we just read back in from a
    // didChangeNotification, which would otherwise recurse forever.
    private var isApplyingExternalChange = false
    private var cancellable: AnyCancellable?

    init(defaults: UserDefaults = .standard) {
        self.defaults = defaults
        self.displayName = defaults.string(forKey: Keys.displayName) ?? ""
        self.theme = AppTheme(rawValue: defaults.string(forKey: Keys.theme) ?? "") ?? .system
        self.notificationsEnabled = defaults.object(forKey: Keys.notificationsEnabled) as? Bool ?? true
        self.refreshInterval = defaults.object(forKey: Keys.refreshInterval) as? TimeInterval ?? 60

        cancellable = NotificationCenter.default
            .publisher(for: UserDefaults.didChangeNotification, object: defaults)
            .receive(on: DispatchQueue.main)
            .sink { [weak self] _ in
                Task { @MainActor in
                    self?.reloadFromDefaults()
                }
            }
    }

    private func persist<T>(_ value: T, forKey key: String) {
        guard !isApplyingExternalChange else { return }
        defaults.set(value, forKey: key)
    }

    private func reloadFromDefaults() {
        isApplyingExternalChange = true
        defer { isApplyingExternalChange = false }

        let newDisplayName = defaults.string(forKey: Keys.displayName) ?? ""
        if newDisplayName != displayName { displayName = newDisplayName }

        let newTheme = AppTheme(rawValue: defaults.string(forKey: Keys.theme) ?? "") ?? .system
        if newTheme != theme { theme = newTheme }

        let newNotificationsEnabled = defaults.object(forKey: Keys.notificationsEnabled) as? Bool ?? true
        if newNotificationsEnabled != notificationsEnabled { notificationsEnabled = newNotificationsEnabled }

        let newRefreshInterval = defaults.object(forKey: Keys.refreshInterval) as? TimeInterval ?? 60
        if newRefreshInterval != refreshInterval { refreshInterval = newRefreshInterval }
    }
}

struct SettingsScreen: View {
    @ObservedObject var store: SettingsStore

    private static let refreshIntervalOptions: [TimeInterval] = [15, 30, 60, 300, 900]

    var body: some View {
        Form {
            Section("Profile") {
                TextField("Display Name", text: $store.displayName)
            }

            Section("Appearance") {
                Picker("Theme", selection: $store.theme) {
                    ForEach(AppTheme.allCases) { theme in
                        Text(theme.displayName).tag(theme)
                    }
                }
            }

            Section("Notifications") {
                Toggle("Enable Notifications", isOn: $store.notificationsEnabled)
            }

            Section("Sync") {
                Picker("Refresh Interval", selection: $store.refreshInterval) {
                    ForEach(Self.refreshIntervalOptions, id: \.self) { interval in
                        Text(Self.label(for: interval)).tag(interval)
                    }
                }
            }
        }
        .navigationTitle("Settings")
    }

    private static func label(for interval: TimeInterval) -> String {
        switch interval {
        case 15: return "15 seconds"
        case 30: return "30 seconds"
        case 60: return "1 minute"
        case 300: return "5 minutes"
        case 900: return "15 minutes"
        default: return "\(Int(interval))s"
        }
    }
}

import { useEffect, useMemo, useRef, useState } from "react";

interface TodoItem {
  id: string;
  text: string;
  done: boolean;
}

type Filter = "all" | "active" | "done";

const STORAGE_KEY = "todo-board:items";

function isTodoItem(value: unknown): value is TodoItem {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.id === "string" &&
    typeof candidate.text === "string" &&
    typeof candidate.done === "boolean"
  );
}

function loadItems(): TodoItem[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed.filter(isTodoItem);
  } catch {
    return [];
  }
}

export default function TodoBoard() {
  const [items, setItems] = useState<TodoItem[]>([]);
  const [hydrated, setHydrated] = useState(false);
  const [filter, setFilter] = useState<Filter>("all");
  const [newText, setNewText] = useState("");
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editingText, setEditingText] = useState("");
  const cancelingEditRef = useRef(false);

  useEffect(() => {
    setItems(loadItems());
    setHydrated(true);
  }, []);

  useEffect(() => {
    if (!hydrated) return;
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
    } catch (error) {
      console.error("Failed to save todo items to storage", error);
    }
  }, [items, hydrated]);

  const remainingCount = useMemo(
    () => items.filter((item) => !item.done).length,
    [items],
  );

  const visibleItems = useMemo(() => {
    switch (filter) {
      case "active":
        return items.filter((item) => !item.done);
      case "done":
        return items.filter((item) => item.done);
      default:
        return items;
    }
  }, [items, filter]);

  function addItem() {
    const text = newText.trim();
    if (!text) return;
    setItems((prev) => [
      ...prev,
      { id: crypto.randomUUID(), text, done: false },
    ]);
    setNewText("");
  }

  function toggleDone(id: string) {
    setItems((prev) =>
      prev.map((item) =>
        item.id === id ? { ...item, done: !item.done } : item,
      ),
    );
  }

  function deleteItem(id: string) {
    setItems((prev) => prev.filter((item) => item.id !== id));
    if (editingId === id) {
      setEditingId(null);
      setEditingText("");
    }
  }

  function startEditing(item: TodoItem) {
    setEditingId(item.id);
    setEditingText(item.text);
  }

  function commitEdit() {
    if (editingId === null) return;
    const text = editingText.trim();
    setItems((prev) =>
      prev.map((item) =>
        item.id === editingId
          ? { ...item, text: text || item.text }
          : item,
      ),
    );
    setEditingId(null);
    setEditingText("");
  }

  function cancelEdit() {
    cancelingEditRef.current = true;
    setEditingId(null);
    setEditingText("");
  }

  function handleEditBlur() {
    if (cancelingEditRef.current) {
      cancelingEditRef.current = false;
      return;
    }
    commitEdit();
  }

  function moveItem(id: string, direction: -1 | 1) {
    setItems((prev) => {
      const index = prev.findIndex((item) => item.id === id);
      const targetIndex = index + direction;
      if (index === -1 || targetIndex < 0 || targetIndex >= prev.length) {
        return prev;
      }
      const next = [...prev];
      [next[index], next[targetIndex]] = [next[targetIndex], next[index]];
      return next;
    });
  }

  return (
    <div>
      <h1>Todo Board</h1>

      <form
        onSubmit={(e) => {
          e.preventDefault();
          addItem();
        }}
      >
        <input
          type="text"
          value={newText}
          onChange={(e) => setNewText(e.target.value)}
          placeholder="Add a new item"
        />
        <button type="submit">Add</button>
      </form>

      <div role="group" aria-label="Filter items">
        {(["all", "active", "done"] as const).map((f) => (
          <button
            key={f}
            type="button"
            aria-pressed={filter === f}
            onClick={() => setFilter(f)}
            disabled={filter === f}
          >
            {f}
          </button>
        ))}
      </div>

      <p>{remainingCount} item(s) remaining</p>

      <ul>
        {visibleItems.map((item) => {
          const index = items.findIndex((i) => i.id === item.id);
          const isEditing = editingId === item.id;
          return (
            <li key={item.id}>
              <input
                type="checkbox"
                checked={item.done}
                onChange={() => toggleDone(item.id)}
                aria-label={`Mark "${item.text}" as ${item.done ? "active" : "done"}`}
              />

              {isEditing ? (
                <form
                  style={{ display: "inline" }}
                  onSubmit={(e) => {
                    e.preventDefault();
                    commitEdit();
                  }}
                >
                  <input
                    type="text"
                    value={editingText}
                    autoFocus
                    onChange={(e) => setEditingText(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === "Escape") cancelEdit();
                    }}
                    onBlur={handleEditBlur}
                  />
                </form>
              ) : (
                <span
                  onDoubleClick={() => startEditing(item)}
                  style={{ textDecoration: item.done ? "line-through" : "none" }}
                >
                  {item.text}
                </span>
              )}

              <button type="button" onClick={() => startEditing(item)}>
                Edit
              </button>
              <button
                type="button"
                onClick={() => moveItem(item.id, -1)}
                disabled={index <= 0}
              >
                Move up
              </button>
              <button
                type="button"
                onClick={() => moveItem(item.id, 1)}
                disabled={index === -1 || index >= items.length - 1}
              >
                Move down
              </button>
              <button type="button" onClick={() => deleteItem(item.id)}>
                Delete
              </button>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

import SwiftUI

struct SearchResult: Identifiable, Decodable, Equatable {
    let id: String
    let title: String
    let subtitle: String
}

@MainActor
final class SearchViewModel: ObservableObject {
    @Published var query: String = ""
    @Published private(set) var results: [SearchResult] = []
    @Published private(set) var isLoading = false
    @Published private(set) var errorMessage: String?

    private let session: URLSession
    private let debounceNanoseconds: UInt64
    private var searchTask: Task<Void, Never>?
    private var currentSearchID: UUID?

    init(session: URLSession = .shared, debounceNanoseconds: UInt64 = 300_000_000) {
        self.session = session
        self.debounceNanoseconds = debounceNanoseconds
    }

    func onQueryChange() {
        searchTask?.cancel()

        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            currentSearchID = nil
            results = []
            errorMessage = nil
            isLoading = false
            return
        }

        // Clear stale content immediately so it isn't mistaken for the new query's results
        // while the debounce timer is running.
        results = []
        errorMessage = nil

        let searchID = UUID()
        currentSearchID = searchID

        searchTask = Task { [weak self, debounceNanoseconds, trimmed, searchID] in
            try? await Task.sleep(nanoseconds: debounceNanoseconds)
            guard !Task.isCancelled else { return }
            guard let self else { return }
            await self.performSearch(for: trimmed, searchID: searchID)
        }
    }

    private func performSearch(for query: String, searchID: UUID) async {
        // A canceled request can still reach this point mid-flight; only the current
        // search is allowed to mutate published state so it can't clobber a newer one.
        guard currentSearchID == searchID else { return }
        isLoading = true
        errorMessage = nil
        defer {
            if currentSearchID == searchID {
                isLoading = false
            }
        }

        guard var components = URLComponents(string: "https://api.example.com/search") else {
            if currentSearchID == searchID {
                errorMessage = "Invalid search URL."
            }
            return
        }
        components.queryItems = [URLQueryItem(name: "q", value: query)]

        guard let url = components.url else {
            if currentSearchID == searchID {
                errorMessage = "Invalid search URL."
            }
            return
        }

        do {
            let (data, response) = try await session.data(from: url)
            guard currentSearchID == searchID else { return }

            if let httpResponse = response as? HTTPURLResponse,
               !(200...299).contains(httpResponse.statusCode) {
                errorMessage = "Server error (\(httpResponse.statusCode))."
                results = []
                return
            }

            let decoded = try JSONDecoder().decode([SearchResult].self, from: data)
            guard currentSearchID == searchID else { return }
            results = decoded
        } catch {
            guard currentSearchID == searchID else { return }
            errorMessage = error.localizedDescription
            results = []
        }
    }
}

struct SearchScreen: View {
    @StateObject private var viewModel = SearchViewModel()

    var body: some View {
        VStack(spacing: 0) {
            TextField("Search", text: $viewModel.query)
                .textFieldStyle(.roundedBorder)
                .padding()
                .onChange(of: viewModel.query) { _ in
                    viewModel.onQueryChange()
                }

            Divider()

            content
        }
        .frame(minWidth: 320, minHeight: 400)
    }

    @ViewBuilder
    private var content: some View {
        let trimmedQuery = viewModel.query.trimmingCharacters(in: .whitespacesAndNewlines)

        if viewModel.isLoading {
            ProgressView("Searching…")
                .frame(maxWidth: .infinity, maxHeight: .infinity)
        } else if let errorMessage = viewModel.errorMessage {
            VStack(spacing: 8) {
                Image(systemName: "exclamationmark.triangle")
                    .foregroundStyle(.red)
                Text(errorMessage)
                    .foregroundStyle(.red)
                    .multilineTextAlignment(.center)
            }
            .padding()
            .frame(maxWidth: .infinity, maxHeight: .infinity)
        } else if trimmedQuery.isEmpty {
            Text("Start typing to search.")
                .foregroundStyle(.secondary)
                .frame(maxWidth: .infinity, maxHeight: .infinity)
        } else if viewModel.results.isEmpty {
            Text("No results found.")
                .foregroundStyle(.secondary)
                .frame(maxWidth: .infinity, maxHeight: .infinity)
        } else {
            List(viewModel.results) { result in
                VStack(alignment: .leading, spacing: 2) {
                    Text(result.title)
                        .font(.headline)
                    Text(result.subtitle)
                        .font(.subheadline)
                        .foregroundStyle(.secondary)
                }
            }
        }
    }
}

import Foundation
import SwiftUI

#if canImport(UIKit)
import UIKit
typealias PlatformImage = UIImage
#elseif canImport(AppKit)
import AppKit
typealias PlatformImage = NSImage
#endif

/// A downloaded thumbnail together with the moment it finished downloading.
struct CachedThumbnail: @unchecked Sendable {
    let image: PlatformImage
    let downloadDate: Date
}

// PlatformImage (UIImage/NSImage) isn't declared Sendable by the SDK, but instances here
// are never mutated after creation, so sharing them across the actor boundary is safe.

/// Shared in-memory cache so scrolling back through the grid doesn't re-download thumbnails.
/// Bounded to `limit` entries (evicted oldest-first) and de-duplicates concurrent downloads
/// of the same URL.
actor ThumbnailCache {
    static let shared = ThumbnailCache()

    private let limit = 200
    private var storage: [URL: CachedThumbnail] = [:]
    private var insertionOrder: [URL] = []
    private var inFlightDownloads: [URL: Task<CachedThumbnail, Error>] = [:]

    func thumbnail(for url: URL) -> CachedThumbnail? {
        storage[url]
    }

    /// Returns the cached thumbnail for `url`, downloading it via `download` if needed.
    /// Concurrent callers for the same uncached `url` share a single in-flight download.
    func thumbnail(for url: URL, download: @escaping @Sendable () async throws -> CachedThumbnail) async throws -> CachedThumbnail {
        if let cached = storage[url] {
            return cached
        }
        if let existing = inFlightDownloads[url] {
            return try await existing.value
        }

        let task = Task { try await download() }
        inFlightDownloads[url] = task
        defer { inFlightDownloads[url] = nil }

        let result = try await task.value
        insert(result, for: url)
        return result
    }

    private func insert(_ thumbnail: CachedThumbnail, for url: URL) {
        if storage[url] == nil {
            insertionOrder.append(url)
        }
        storage[url] = thumbnail

        while insertionOrder.count > limit {
            let oldest = insertionOrder.removeFirst()
            storage[oldest] = nil
        }
    }
}

/// A grid of photo thumbnails downloaded from `urls`, showing a placeholder while each
/// image loads and the relative download date once it's available.
struct ThumbnailGrid: View {
    let urls: [URL]

    private let columns = [GridItem(.adaptive(minimum: 100, maximum: 160), spacing: 8)]

    var body: some View {
        ScrollView {
            LazyVGrid(columns: columns, spacing: 8) {
                ForEach(urls, id: \.self) { url in
                    ThumbnailCell(url: url)
                }
            }
            .padding(8)
        }
    }
}

private struct ThumbnailCell: View {
    let url: URL

    @State private var thumbnail: CachedThumbnail?
    @State private var failed = false

    var body: some View {
        VStack(spacing: 4) {
            ZStack {
                RoundedRectangle(cornerRadius: 8)
                    .fill(Color.secondary.opacity(0.15))

                if let thumbnail {
                    thumbnailImage(thumbnail.image)
                        .resizable()
                        .aspectRatio(contentMode: .fill)
                        .clipShape(RoundedRectangle(cornerRadius: 8))
                } else if failed {
                    Image(systemName: "photo")
                        .foregroundStyle(.secondary)
                } else {
                    ProgressView()
                }
            }
            .aspectRatio(1, contentMode: .fit)

            if let downloadDate = thumbnail?.downloadDate {
                Text(downloadDate, format: .relative(presentation: .named))
                    .font(.caption2)
                    .foregroundStyle(.secondary)
            }
        }
        .task(id: url) {
            await load()
        }
    }

    private func thumbnailImage(_ image: PlatformImage) -> Image {
        #if canImport(UIKit)
        return Image(uiImage: image)
        #elseif canImport(AppKit)
        return Image(nsImage: image)
        #endif
    }

    private func load() async {
        thumbnail = nil
        failed = false

        do {
            let result = try await ThumbnailCache.shared.thumbnail(for: url) {
                let (data, response) = try await URLSession.shared.data(from: url)
                guard let httpResponse = response as? HTTPURLResponse,
                      (200..<300).contains(httpResponse.statusCode) else {
                    throw URLError(.badServerResponse)
                }
                guard let image = PlatformImage(data: data) else {
                    throw URLError(.cannotDecodeContentData)
                }
                return CachedThumbnail(image: image, downloadDate: Date())
            }
            guard !Task.isCancelled else { return }
            thumbnail = result
        } catch {
            guard !Task.isCancelled else { return }
            failed = true
        }
    }
}

import Foundation
import SwiftUI

struct ChatMessage: Identifiable, Codable, Equatable {
    let id: String
    let author: String
    let text: String
}

@MainActor
final class ChatViewModel: ObservableObject {
    @Published var messages: [ChatMessage] = []
    @Published var draftText: String = ""

    private let url: URL = {
        guard let url = URL(string: "wss://chat.example.com/room") else {
            preconditionFailure("Invalid chat room URL")
        }
        return url
    }()
    private let session = URLSession(configuration: .default)
    private var webSocketTask: URLSessionWebSocketTask?
    private var reconnectTask: Task<Void, Never>?
    private var reconnectDelay: TimeInterval = 1
    private let maxReconnectDelay: TimeInterval = 30
    private var isStopped = false
    private var connectionID = 0

    func start() {
        guard webSocketTask == nil, reconnectTask == nil else { return }
        isStopped = false
        connect()
    }

    func stop() {
        isStopped = true
        connectionID += 1
        reconnectTask?.cancel()
        reconnectTask = nil
        webSocketTask?.cancel(with: .goingAway, reason: nil)
        webSocketTask = nil
    }

    private func connect() {
        reconnectTask = nil
        connectionID += 1
        let id = connectionID
        let task = session.webSocketTask(with: url)
        webSocketTask = task
        task.resume()
        receiveNext(id: id, task: task)
    }

    private func receiveNext(id: Int, task: URLSessionWebSocketTask) {
        task.receive { [weak self] result in
            Task { @MainActor [weak self] in
                guard let self, self.connectionID == id else { return }
                switch result {
                case .success(let message):
                    self.reconnectDelay = 1
                    self.handle(message)
                    self.receiveNext(id: id, task: task)
                case .failure:
                    self.scheduleReconnect(id: id)
                }
            }
        }
    }

    private func handle(_ message: URLSessionWebSocketTask.Message) {
        let data: Data?
        switch message {
        case .data(let raw):
            data = raw
        case .string(let text):
            data = text.data(using: .utf8)
        @unknown default:
            data = nil
        }
        guard let data, let chatMessage = try? JSONDecoder().decode(ChatMessage.self, from: data) else { return }
        messages.append(chatMessage)
    }

    private func scheduleReconnect(id: Int) {
        guard id == connectionID, !isStopped, reconnectTask == nil else { return }
        webSocketTask = nil
        let delay = reconnectDelay
        reconnectDelay = min(reconnectDelay * 2, maxReconnectDelay)
        reconnectTask = Task { [weak self] in
            try? await Task.sleep(nanoseconds: UInt64(delay * 1_000_000_000))
            guard let self, !Task.isCancelled else { return }
            guard self.connectionID == id, !self.isStopped else { return }
            self.connect()
        }
    }

    func sendDraft() {
        let trimmed = draftText.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty, let task = webSocketTask else { return }
        let id = connectionID
        let outgoing = ChatMessage(id: UUID().uuidString, author: "me", text: trimmed)
        guard let data = try? JSONEncoder().encode(outgoing) else { return }
        messages.append(outgoing)
        draftText = ""
        task.send(.data(data)) { [weak self] error in
            guard error != nil else { return }
            Task { @MainActor [weak self] in
                guard let self, self.connectionID == id else { return }
                self.messages.removeAll { $0.id == outgoing.id }
                if self.draftText.isEmpty {
                    self.draftText = trimmed
                }
                self.scheduleReconnect(id: id)
            }
        }
    }
}

struct ChatScreen: View {
    @StateObject private var viewModel = ChatViewModel()

    var body: some View {
        VStack(spacing: 0) {
            ScrollViewReader { proxy in
                ScrollView {
                    LazyVStack(alignment: .leading, spacing: 8) {
                        ForEach(viewModel.messages) { message in
                            VStack(alignment: .leading, spacing: 2) {
                                Text(message.author)
                                    .font(.caption)
                                    .foregroundStyle(.secondary)
                                Text(message.text)
                            }
                            .id(message.id)
                            .frame(maxWidth: .infinity, alignment: .leading)
                        }
                    }
                    .padding()
                }
                .onChange(of: viewModel.messages) { _ in
                    scrollToBottom(proxy: proxy)
                }
                .onAppear {
                    scrollToBottom(proxy: proxy)
                }
            }

            Divider()

            HStack {
                TextField("Message", text: $viewModel.draftText)
                    .textFieldStyle(.roundedBorder)
                    .onSubmit { viewModel.sendDraft() }
                Button("Send") { viewModel.sendDraft() }
                    .disabled(viewModel.draftText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
            }
            .padding()
        }
        .onAppear { viewModel.start() }
        .onDisappear { viewModel.stop() }
    }

    private func scrollToBottom(proxy: ScrollViewProxy) {
        guard let lastId = viewModel.messages.last?.id else { return }
        withAnimation {
            proxy.scrollTo(lastId, anchor: .bottom)
        }
    }
}

import Foundation

// MARK: - Legacy callback-based SDK (stubs)

final class LegacyGeocoder {
    func geocode(_ address: String, completion: @escaping (Result<(Double, Double), Error>) -> Void) {
        DispatchQueue.global().asyncAfter(deadline: .now() + 0.1) {
            completion(.success((37.7749, -122.4194)))
        }
    }
}

final class LegacyUploader {
    var onProgress: ((Double) -> Void)?
    var onFinish: ((Error?) -> Void)?

    func start(file: URL) {
        DispatchQueue.global().async {
            for step in 1...10 {
                Thread.sleep(forTimeInterval: 0.01)
                self.onProgress?(Double(step) / 10.0)
            }
            self.onFinish?(nil)
        }
    }
}

// MARK: - Modern async/await wrappers

/// Resumes a `CheckedContinuation` exactly once, whichever of the legacy
/// callback or the task-cancellation handler reaches it first. If the
/// cancellation handler fires before the continuation has been created
/// (the operation and `onCancel` may race), the result is buffered and
/// delivered as soon as `setContinuation` is called.
private final class CancellableContinuation<T> {
    private let lock = NSLock()
    private var continuation: CheckedContinuation<T, Error>?
    private var pendingResult: Result<T, Error>?
    private var didResume = false

    func setContinuation(_ continuation: CheckedContinuation<T, Error>) {
        lock.lock()
        if let pendingResult {
            self.pendingResult = nil
            lock.unlock()
            continuation.resume(with: pendingResult)
            return
        }
        self.continuation = continuation
        lock.unlock()
    }

    func resume(with result: Result<T, Error>) {
        lock.lock()
        guard !didResume else {
            lock.unlock()
            return
        }
        didResume = true
        if let continuation {
            self.continuation = nil
            lock.unlock()
            continuation.resume(with: result)
        } else {
            pendingResult = result
            lock.unlock()
        }
    }
}

final class ModernGeocoder {
    private let legacy = LegacyGeocoder()

    func geocode(_ address: String) async throws -> (Double, Double) {
        try Task.checkCancellation()
        let box = CancellableContinuation<(Double, Double)>()
        return try await withTaskCancellationHandler {
            try await withCheckedThrowingContinuation { continuation in
                box.setContinuation(continuation)
                legacy.geocode(address) { result in
                    box.resume(with: result)
                }
            }
        } onCancel: {
            // LegacyGeocoder exposes no cancellation hook, so the in-flight
            // callback cannot be aborted, but the caller is released
            // immediately instead of waiting for it to complete.
            box.resume(with: .failure(CancellationError()))
        }
    }
}

final class ModernUploader {
    /// Each call gets its own progress stream and completion task, so
    /// concurrent or sequential uploads never contend for the same
    /// continuation.
    func upload(file: URL) -> (progress: AsyncStream<Double>, result: Task<Void, Error>) {
        var progressContinuation: AsyncStream<Double>.Continuation!
        let progressStream = AsyncStream<Double> { progressContinuation = $0 }

        let task = Task {
            try Task.checkCancellation()
            let legacy = LegacyUploader()
            let box = CancellableContinuation<Void>()
            try await withTaskCancellationHandler {
                try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in
                    box.setContinuation(continuation)
                    legacy.onProgress = { progress in
                        progressContinuation.yield(progress)
                    }
                    legacy.onFinish = { error in
                        progressContinuation.finish()
                        if let error {
                            box.resume(with: .failure(error))
                        } else {
                            box.resume(with: .success(()))
                        }
                    }
                    legacy.start(file: file)
                }
            } onCancel: {
                // LegacyUploader exposes no cancellation hook, so the
                // in-flight upload cannot be aborted, but the caller and
                // any progress observers are released immediately instead
                // of waiting for it to complete.
                progressContinuation.finish()
                box.resume(with: .failure(CancellationError()))
            }
        }

        return (progressStream, task)
    }
}
